L16_1.m_Talk_SCN = "如果我输了……那也只是……将计划移交给下一个人罢了。"
L16_1.m_Talk_DEU = "Ich mag vielleicht versagt haben, aber … andere werden kommen und unser Werk fortsetzen …"
L16_1.m_Talk_FRA = "J'ai peut-être échoué, mais... quelqu'un d'autre viendra reprendre notre flambeau..."
