L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "余計な未練は捨てれば？　すでにリプレイサーの組織全体が崩壊してるんだから。"
L17_1.m_Talk_ENG = "Just let it go. The Replacer Syndicate has completely been destroyed."
