L17_1.m_Talk_VTN = "Bỏ đi. Nghiệp Đoàn Nhân Bản đã hoàn toàn bị phá hủy."
L17_1.m_Talk_SCN = "放下这些没用的留恋吧。克隆集团组织也已经全盘崩溃了。"
L17_1.m_Talk_DEU = "Das kannst du dir abschminken. Das Replacer-Syndikat wurde komplett zerschlagen."
