L32_1 = "FX_CUTSCEN_SIREN"
L31_1.m_StartFXSoundName = L32_1
L32_1 = "<color=#ffd34c>긴급경보. 양자터널 유지 한계에 도달했습니다.</color>"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "<color=#ffd34c>緊急警報。量子トンネルは維持限界に達しました。</color>"
L31_1.m_Talk_JPN = L32_1
L32_1 = "<color=#ffd34c>Alert. The quantum tunnel is expiring shortly.</color>"
L31_1.m_Talk_ENG = L32_1
L32_1 = "<color=#ffd34c>緊急警報，量子隧道到達維持極限。</color>"
L31_1.m_Talk_TWN = L32_1
L32_1 = "<color=#ffd34c>ระวัง อุโมงค์ควอนตัมจะหมดอายุในเร็วๆ นี้</color>"
L31_1.m_Talk_THA = L32_1
L32_1 = "<color=#ffd34c>Cảnh báo. Đường hầm lượng tử sắp hết hạn.</color>"
L31_1.m_Talk_VTN = L32_1
L32_1 = "<color=#ffd34c>紧急警报，量子隧道到达维持极限。</color>"
L31_1.m_Talk_SCN = L32_1
L32_1 = "<color=#ffd34c>Alarm! Der Quantumtunnel bricht in Kürze zusammen.</color>"
L31_1.m_Talk_DEU = L32_1
L32_1 = "<color=#ffd34c>Alerte. Expiration du tunnel quantique imminente.</color>"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EP5_ACT5_STAGE6_END@32#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 32
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 215
L32_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "<color=#ffd34c>내부 체류중인 인원은 즉시 터널에서 퇴거하시기 바랍니다.</color>"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "<color=#ffd34c>内部滞在中の人員は、ただちにトンネルから退去してください。</color>"
L32_1.m_Talk_JPN = L33_1
L33_1 = "<color=#ffd34c>Any personnel inside the tunnel must evacuate immediately.</color>"
L32_1.m_Talk_ENG = L33_1
L33_1 = "<color=#ffd34c>請滯留於隧道內部的人員立即撤出。</color>"
L32_1.m_Talk_TWN = L33_1
L33_1 = "<color=#ffd34c>เจ้าหน้าที่ที่อยู่ข้างในต้องอพยพทันที</color>"
L32_1.m_Talk_THA = L33_1
L33_1 = "<color=#ffd34c>Tất cả mọi người trong đường hầm phải sơ tán ngay lập tức.</color>"
L32_1.m_Talk_VTN = L33_1
L33_1 = "<color=#ffd34c>请滞留于隧道内部人员立即撤出。</color>"
L32_1.m_Talk_SCN = L33_1
L33_1 = "<color=#ffd34c>Sämtliche Personen innerhalb des Tunnels sind sofort zu evakuieren.</color>"
L32_1.m_Talk_DEU = L33_1
L33_1 = "<color=#ffd34c>Toute personne présente dans le tunnel doit évacuer immédiatement.</color>"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
