L33_1.m_fBGCrashTime = 2
L34_1 = "FX_CUTSCEN_BOOM"
L33_1.m_StartFXSoundName = L34_1
L34_1 = "<color=#ffd34c>양자터널 붕괴 시 내부 체류중인 인원은 영구적으로 허수공간 밖으로 배출됩니다.</color>"
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "<color=#ffd34c>量子トンネルが崩壊すると、内部滞在中の人員は永久に虚数空間外に排出されます。</color>"
L33_1.m_Talk_JPN = L34_1
L34_1 = "<color=#ffd34c>The quantum tunnel will release everything inside it into the imaginary space upon collapsing.</color>"
L33_1.m_Talk_ENG = L34_1
L34_1 = "<color=#ffd34c>量子隧道崩潰時，滯留於內部的人員將被永久排出至虛數空間。</color>"
L33_1.m_Talk_TWN = L34_1
L34_1 = "<color=#ffd34c>อุโมงค์ควอนตัมจะปลดปล่อยทุกสิ่งข้างในเข้าสู่พื้นที่จินตภาพเมื่ออุโมงค์สลาย</color>"
L33_1.m_Talk_THA = L34_1
L34_1 = "<color=#ffd34c>Đường hầm lượng tử sẽ giải phóng mọi thứ bên trong vào không gian tưởng tượng khi sụp đổ.</color>"
L33_1.m_Talk_VTN = L34_1
L34_1 = "<color=#ffd34c>量子隧道崩溃时，滞留于内部的人员将被永久排出虚空。</color>"
L33_1.m_Talk_SCN = L34_1
L34_1 = "<color=#ffd34c>Nach einem Zusammenbruch wird alles innerhalb des Quantumtunnels in den imaginären Raum geschleudert.</color>"
L33_1.m_Talk_DEU = L34_1
L34_1 = "<color=#ffd34c>En s'effondrant, le tunnel quantique va libérer tout ce qu'il contient dans l'espace imaginaire.</color>"
L33_1.m_Talk_FRA = L34_1
