L37_1 = "量子トンネルが崩壊すると……この中にあるすべての物質は……虚数空間に排出される……"
L36_1.m_Talk_JPN = L37_1
L37_1 = "If this quantum tunnel collapses, everything in here will be thrown away to the imaginary space."
L36_1.m_Talk_ENG = L37_1
L37_1 = "量子隧道崩壞的話……隧道中所有物質……都會被排放至虛數空間……"
L36_1.m_Talk_TWN = L37_1
L37_1 = "หากอุโมงค์ควอนตัมสลาย ทุกอย่างในนี้จะถูกเหวี่ยงเข้าสู่พื้นที่จินตภาพ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Nếu đường hầm lượng tử này sụp đổ, mọi thứ trong đó sẽ bị ném vào không gian tưởng tượng."
L36_1.m_Talk_VTN = L37_1
L37_1 = "如果量子隧道崩溃了……隧道中所有物质……都会被排放入虚空……"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Wenn dieser Quantumtunnel zusammenbricht, wird alles hier in den imaginären Raum geschleudert."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Si ce tunnel s'effondre, tout ce qui s'y trouve va être projeté dans l'espace imaginaire."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
