L38_1.m_Face = "UNIT_IDLE"
L38_1.m_CharStrID = "KING_REPLACER_NULL_TRANS"
L38_1.m_Crash = 20
L39_1 = "영원히 무한한 공간을 떠도는 신세가 되고 싶진 않겠지?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "永遠に無限の空間をさまよいたくはないだろう？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "You don't want to end up wandering around infinity forever, do you?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "妳應該不想在無限的空間中永遠漂泊吧？"
L38_1.m_Talk_TWN = L39_1
L39_1 = "คุณคงไม่อยากลงเอยด้วยการเดินอยู่ในนิรันดรตลอดกาลใช่ไหม?"
L38_1.m_Talk_THA = L39_1
L39_1 = "Bạn không muốn suốt đời lang thang trong không gian vô cực phải không?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "你应该不想在无限的空间中永远漂泊吧？"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Du willst doch nicht auf ewig in der Unendlichkeit herumirren, oder?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Vous ne souhaitez pas finir errant pour l'éternité dans le néant, n'est-ce pas ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
