L16_1.m_fTalkTime = 0.03
L17_1 = "コフィン艦の医務室だ。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "You're in the Coffin's sickbay."
L16_1.m_Talk_ENG = L17_1
L17_1 = "這裡是科芬艦的醫務室。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "คุณอยู่ในแผนกผู้ป่วยของคอฟฟิน"
L16_1.m_Talk_THA = L17_1
L17_1 = "Bạn đang ở trong bệnh xá của Coffin."
L16_1.m_Talk_VTN = L17_1
L17_1 = "这里是科芬舰的医务室。"
