L18_1 = "EP5_ACT5_STAGE6_END@67#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 67
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 215
L17_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "HILDE_FENRIR_NULL_NULL"
L17_1.m_CharStrID = L18_1
L18_1 = "R"
L17_1.m_Pos = L18_1
L18_1 = "양자 터널에서 배출되는 게 몇 초만 늦었어도 널 회수하지 못했을 거야."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "量子トンネルからの脱出が数秒遅れたら、お前を回収できなかっただろうな。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "If you had been thrown out of the quantum tunnel a few seconds later, we wouldn't have been able to save you."
L17_1.m_Talk_ENG = L18_1
L18_1 = "妳要是再晚個幾秒撤出量子遂道，我們就沒辦法找回妳了。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "ถ้าคุณถูกโยนออกจากอุโมงค์ควอนตัมช้ากว่านี้ไม่กี่วินาที เราคงช่วยคุณไว้ไม่ได้"
L17_1.m_Talk_THA = L18_1
L18_1 = "Nếu bạn bị ném ra khỏi đường hầm lượng tử chỉ chậm vài giây sau đó, chúng tôi sẽ không thể cứu bạn."
L17_1.m_Talk_VTN = L18_1
L18_1 = "你要是再晚几秒撤出量子遂道，我们就没法找回你了。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Wenn du auch nur ein paar Sekunden später aus dem Quantumtunnel herausgeschleudert worden wärst, hätten wir dich nicht mehr retten können."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Si vous aviez été projetée du tunnel quantique quelques secondes plus tard, nous n'aurions pas été capables de vous sauver."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "EP5_ACT5_STAGE6_END@68#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 68
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 215
L18_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L18_1.m_bWaitClick = true
