L19_1 = "HILDE_FENRIR_NULL_NULL"
L18_1.m_CharStrID = L19_1
L19_1 = "R"
L18_1.m_Pos = L19_1
L19_1 = "네가 제법 운이 좋은 건 사실이지만 앞으로는 이런 무모한 짓은 자제하도록,"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "お前は運がいいのは事実だが、今後はこんな無謀なことは慎むように。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "You've been quite lucky until now, but I forbid you from doing something so reckless in the future."
L18_1.m_Talk_ENG = L19_1
L19_1 = "雖然妳運氣確實很好，但以後請少做這種魯莽的行為。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "คุณโชคดีมากนะ แต่ฉันขอห้ามไม่ให้คุณทำอะไรบุ่มบ่ามแบบนั้นอีกในอนาคต"
L18_1.m_Talk_THA = L19_1
L19_1 = "Cho đến giờ bạn đã khá may mắn, nhưng tôi cấm bạn liều lĩnh như vậy trong tương lai."
L18_1.m_Talk_VTN = L19_1
L19_1 = "虽然你确实运气很好，但以后还是少干这种鲁莽事，"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Bis jetzt hattest du Glück, aber ich verbiete dir, in Zukunft noch einmal so leichtsinnig zu sein."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Vous avez eu de la chance jusqu'à présent, mais je vous interdis de refaire quelque chose d'aussi imprudent à l'avenir."
L18_1.m_Talk_FRA = L19_1
