L25_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "C"
L25_1 = "뉴 오하이오와 인근 지역은 양자 터널 붕괴의 여파로 소멸했습니다."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "ニューオハイオと近隣地域は、量子トンネルの崩壊の影響で消滅しました。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "The New Ohio and surrounding area got swept away by the blast caused by the quantum tunnel's collapse and disappeared."
L24_1.m_Talk_ENG = L25_1
L25_1 = "新俄亥俄和附近地區都因為量子隧道崩潰的餘波消滅了。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "นิวโอไฮโอและพื้นที่โดยรอบถูกซัดกระจุยจากแรงระเบิดตอนที่อุโมงค์ควอนตัมทลายและหายไป"
L24_1.m_Talk_THA = L25_1
L25_1 = "Tân Ohio và khu vực xung quanh bị cuốn bay bởi vụ nổ do hầm lượng tử sụp đổ và biến mất."
L24_1.m_Talk_VTN = L25_1
L25_1 = "伊欧和附近地区都被量子隧道崩溃的余波消灭了。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Die New Ohio und alles in ihrer Umgebung wurde durch die Explosion des einstürzenden Quantumtunnels fortgeschleudert und ist verschwunden."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Le New Ohio et la zone alentour ont été balayés par l'explosion provoquée par l'effondrement du tunnel quantique et ont disparu."
L24_1.m_Talk_FRA = L25_1
