L26_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L25_1.m_CharStrID = L26_1
L25_1.m_Pos = "C"
L26_1 = "전 세계에 퍼진 이상침식 증후군도 진행을 멈췄고요."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "世界中に広まった異常侵食症候群も進行が止まりましたし。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "The global spread of Corruption Syndrome has also stopped."
L25_1.m_Talk_ENG = L26_1
L26_1 = "蔓延全球的異常侵蝕症候群也停止了。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "การแพร่ระบาดทั่วโลกของกลุ่มอาการคอร์รัปชั่นก็หยุดลงแล้ว"
L25_1.m_Talk_THA = L26_1
L26_1 = "Sự lây lan Hội Chứng Ăn Mòn trên toàn cầu cũng đã dừng lại."
L25_1.m_Talk_VTN = L26_1
L26_1 = "世界范围内爆发的异常侵蚀症候群也停止了。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Die globale Ausbreitung des Verderbnissyndroms wurde gestoppt."
L25_1.m_Talk_DEU = L26_1
L26_1 = "La pandémie globale de syndrome de corruption s'est également arrêtée."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP5_ACT5_STAGE6_END@76#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 76
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 215
L26_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "C"
L27_1 = "생산된 리플레이서 인자들은 대부분 클리포트 레플리카 인자 조합용 재료로 전송되었기 때문에 붕괴와 함께 소멸한 것으로 추정됩니다."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "生産されたリプレイサーファクターは、大半がクリフォト・レプリカ・ファクターの\n組み合わせ材料として転送されたため、崩壊とともに消滅したものとみられます。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "We assume most of the previously produced Replacer Factors have perished along with the explosion, since they had been sent to the New Ohio for Qliphoth Replica Factor production."
L26_1.m_Talk_ENG = L27_1
L27_1 = "生產出來的克隆因子大多都被送去當作逆卡巴拉複製因子的組合原材，推測應該是隨著崩壞一起消滅了。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "เราเชื่อว่ารีเพลสเซอร์แฟกเตอร์ส่วนใหญ่ที่ถูกสร้างขึ้นก่อนหน้านี้ก็หายไปพร้อมกับการระเบิด เพราะพวกมันถูกส่งไปที่นิวโอไฮโอสำหรับการผลิตคลิฟอธแฟกเตอร์จำลอง"
L26_1.m_Talk_THA = L27_1
L27_1 = "Chúng tôi cho rằng hầu hết các Nhân Tố Nhân Bản được sản xuất trước đây đã biến mất cùng với vụ nổ, vì chúng đã được gửi đến Tân Ohio để sản xuất Nhân Tố Nhân Bản Qliphoth."
L26_1.m_Talk_VTN = L27_1
L27_1 = "生产出的克隆因子大都被作为复制神圣因子的组合原材料传送过来了，应该是在崩溃中一起消失了。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Wir gehen davon aus, dass die meisten zuvor produzierten Replacer-Faktoren in der Explosion vernichtet wurden, da sie zur Herstellung nachgemachter Klippot-Faktoren auf die New Ohio gebracht worden waren."
L26_1.m_Talk_DEU = L27_1
L27_1 = "On suppose que la plupart des agents substituteurs ont été tués par l'explosion, puisqu'ils avaient été envoyés sur le New Ohio pour la production de répliques d'agent qliphoth."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
