L30_1 = "EP5_ACT5_STAGE6_END@79#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 79
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 215
L29_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L30_1 = "아, 그분들도 모두 탑승하고 계세요. 같이 현실세계로 부상해야 하니까요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "あ、彼らも全員搭乗しています。一緒に現実世界に戻らないといけないですからね。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Ah, they're all on board. We're taking everyone to the Normalside."
L29_1.m_Talk_ENG = L30_1
L30_1 = "啊，其他人也都搭乘了科芬艦，畢竟他們得躍出現世才行。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "อ๋อ ทุกคนอยู่บนยาน เรากำลังพาทุกคนไปที่นอร์มอลไซด์"
L29_1.m_Talk_THA = L30_1
L30_1 = "À, tất cả đều ở trên tàu. Chúng tôi đang đưa mọi người đến Normalside."
L29_1.m_Talk_VTN = L30_1
L30_1 = "啊，其他人也都搭乘了科芬舰，毕竟得一起跃回现世。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Die sind alle an Bord. Wir bringen sie auf die Normside."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Ils sont à bord. On ramène tout le monde dans le Vérimonde."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
