L30_1.m_Face = L31_1
L31_1 = "JOHN_MASON_NULL_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "C"
L31_1 = "좀 다치긴 했지만 이 정도로 주저앉을 약골은 아니지."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "少しケガはしたが、この程度で挫けるほど軟弱者ではないんだ。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "I'm all scratched here and there, but I'll manage."
L30_1.m_Talk_ENG = L31_1
L31_1 = "雖然也受了點傷，但我們可不是會因為這樣就中途放棄的軟腳蝦。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ผมได้แผลทั้งตัว แต่ไม่เป็นไรหรอก"
L30_1.m_Talk_THA = L31_1
L31_1 = "Tôi bị trầy xước chỗ này chỗ nọ một chút, nhưng tôi sẽ xử lý ổn cả."
L30_1.m_Talk_VTN = L31_1
L31_1 = "虽然也受了点伤，不过他们没那么脆弱。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Ich bin zwar grün und blau, aber ich schaffe das schon."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Je suis égratigné de partout, mais je m'en sortirai."
L30_1.m_Talk_FRA = L31_1
