L34_1 = "UNIT_PRIDE"
L33_1.m_Face = L34_1
L34_1 = "JOHN_MASON_NULL_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "고맙다는 인사를 해야겠군."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "礼を言わないとな。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "I should thank you."
L33_1.m_Talk_ENG = L34_1
L34_1 = "我得跟妳道謝才行。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ผมต้องขอบคุณคุณนะ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Tôi nên cảm ơn bạn."
L33_1.m_Talk_VTN = L34_1
L34_1 = "我得说声谢谢。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Ich möchte dir danken."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Je dois te remercier."
L33_1.m_Talk_FRA = L34_1
