L35_1 = "EP5_ACT5_STAGE6_END@84#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 84
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 215
L34_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L35_1 = "JOHN_MASON_NULL_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "덕분에 이젠 형도 천국에서 두 발 뻗고 잘 살고 있을 거야."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "嬢ちゃんのおかげで、兄貴も天国で安心してるだろうよ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "My brother can finally rest in peace in heaven."
L34_1.m_Talk_ENG = L35_1
L35_1 = "多虧了妳，我哥現在也能在天國安息了吧。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ในที่สุดพี่ชายผมก็จะได้พักอย่างสงบบนสวรรค์"
L34_1.m_Talk_THA = L35_1
L35_1 = "Anh tôi cuối cùng cũng có thể yên nghỉ trên thiên đường."
L34_1.m_Talk_VTN = L35_1
L35_1 = "多亏了你，现在大哥在天国应该也能踏实地好好活着吧。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Mein Bruder kann endlich im Himmel in Frieden ruhen."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Mon frère peut enfin reposer en paix au paradis."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP5_ACT5_STAGE6_END@85#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 85
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 215
L35_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "JANE_MASON_NULL_NULL"
L35_1.m_CharStrID = L36_1
L36_1 = "R_M_I"
L35_1.m_Pos = L36_1
L36_1 = "뭐야? 그런 거 믿는 쪽이었어?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "なになに？　そんなの信じるたちだったの？"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Huh? I didn't know you were a religious type."
L35_1.m_Talk_ENG = L36_1
L36_1 = "什麼？你竟然會相信那種東西？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "หืม? ไม่ยังรู้ว่านายเชื่อเรื่องศาสนาด้วย"
L35_1.m_Talk_THA = L36_1
L36_1 = "Hử? Tôi không biết bạn thuộc tuýp người tin vào tôn giáo."
L35_1.m_Talk_VTN = L36_1
L36_1 = "什么？你竟然会相信这种东西吗？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Ich wusste gar nicht, dass du so religiös bist."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Euh ? Je ne savais pas que vous étiez du genre religieux."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP5_ACT5_STAGE6_END@86#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 86
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 215
L36_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_Face = "UNIT_HATE"
L37_1 = "JOHN_MASON_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "이런 건 관용어구라고 하는 거다, 관용어구. 시비 좀 걸지 마."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "こういうのを慣用表現というんだ。いちいち食ってかかるな。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "It's a figure of speech. Do you really have to pick on every word I say?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "這只是慣用語啦，慣用語，不要挑我語病啦。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "มันก็แค่สำนวน ทำไมต้องจับผิดทุกคำที่ผมพูดด้วย?"
L36_1.m_Talk_THA = L37_1
L37_1 = "Chỉ là một cách nói thôi. Bạn có thực sự phải soi xét từng lời tôi nói không?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "这只是惯用语啦，惯用语。别找茬。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Das sagt man eben so. Musst du eigentlich jedes Wort auf die Goldwaage legen?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "C'est une façon de parler. Vous êtes obligée de reprendre tout ce que je dis ?"
L36_1.m_Talk_FRA = L37_1
