L42_1 = "YUMI_POLICE_NULL_NULL"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "C"
L42_1 = "덕분에 엘릭서 관련 사건을 완전히 마무리 지을 수 있었습니다."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "おかげで、エリクサー関連の事件を完全に終結させることができました。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Thanks to you, all the Elixir-related cases came to a close."
L41_1.m_Talk_ENG = L42_1
L42_1 = "多虧有妳，聖水相關事件終於可以結案了。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "คุณทำให้เราปิดคดีที่เกี่ยวข้องกับเอลิกเซอร์ทั้งหมดได้"
L41_1.m_Talk_THA = L42_1
L42_1 = "Nhờ bạn, tất cả các vụ án liên quan đến Nước Thánh đã kết thúc."
L41_1.m_Talk_VTN = L42_1
L42_1 = "多亏有你，我们终于可以了结圣水相关事件。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Dank Ihnen konnten wir alle Fälle im Zusammenhang mit dem Elixier abschließen."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Grâce à vous, toutes les affaires liées à l'élixir peuvent être classées."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
