L42_1.m_Face = "UNIT_SERIOUS"
L43_1 = "YUMI_POLICE_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L43_1 = "이 공로는 반드시 상부에 보고를......"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "今回の手柄は必ず上に報告を……"
L42_1.m_Talk_JPN = L43_1
L43_1 = "I'll make sure the authorities know of your achievements—"
L42_1.m_Talk_ENG = L43_1
L43_1 = "妳的這份功勞我們一定會報告給上級……"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ฉันจะรายงานความสำเร็จของคุณให้เจ้าหน้าที่รับทราบ..."
L42_1.m_Talk_THA = L43_1
L43_1 = "Tôi sẽ đảm bảo các nhà chức trách biết về thành tích của bạn—"
L42_1.m_Talk_VTN = L43_1
L43_1 = "你的这份功劳我们一定会报告上级……"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Ich werde dafür sorgen, dass die Behörden von Ihrer Leistung erfahren …"
L42_1.m_Talk_DEU = L43_1
L43_1 = "Je m'assurerai que les autorités soient au courant de vos exploits..."
L42_1.m_Talk_FRA = L43_1
