L46_1 = "R_M_I"
L45_1.m_Pos = L46_1
L46_1 = "아이 참, 경정님은 항상 그렇게 딱딱한 게 문제라니까요."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "もうっ、警視様はいつもそうやって堅いんですから。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Come on, Major. You should really stop sounding so mechanical all the time."
L45_1.m_Talk_ENG = L46_1
L46_1 = "唉，警正總是這麼死板。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ไม่เอาน่า สารวัตร เธอควรจะเลิกพูดจาเหมือนหุ่นยนต์ตลอดเวลาได้แล้วนะ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Thôi nào, Thiếu Tá. Bạn thực sự nên thôi việc lúc nào cũng máy móc như vậy."
L45_1.m_Talk_VTN = L46_1
L46_1 = "唉，警长老是这么死板啊。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "Jetzt komm schon, Major. Du hörst dich ja an wie eine Maschine."
L45_1.m_Talk_DEU = L46_1
L46_1 = "Allons, major. Vous parlez toujours de manière si mécanique."
L45_1.m_Talk_FRA = L46_1
