L47_1 = "SOYEONG_POLICE_NULL_NULL"
L46_1.m_CharStrID = L47_1
L47_1 = "R"
L46_1.m_Pos = L47_1
L47_1 = "이럴 땐 감사합니다~ 언니~ 라고 하는 거라고요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "こういう時は、ありがとうございました、お姉ちゃん～って言えばいいんですよ。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Just say, \"Thank you, Big Sister.\""
L46_1.m_Talk_ENG = L47_1
L47_1 = "這種時候應該說“謝謝啦~姐姐~”"
L46_1.m_Talk_TWN = L47_1
L47_1 = "แค่บอกว่า “ขอบคุณ พี่สาว” ก็พอ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Chỉ cần nói, \"Cảm ơn, Chị Gái\" thôi."
L46_1.m_Talk_VTN = L47_1
L47_1 = "这种时候应该说“谢谢啦~姐姐~”"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Sag einfach: „Danke, große Schwester.“"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Dites simplement : « Merci, grande sœur. »"
L46_1.m_Talk_FRA = L47_1
