L49_1 = "R"
L48_1.m_Pos = L49_1
L49_1 = "유미나 씨가 연상 아닌가?"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "ミナさんのほうが年上なのでは？"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Ms. Yoo Mina is older than you, no?"
L48_1.m_Talk_ENG = L49_1
L49_1 = "劉米娜小姐不是比妳大嗎？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "คุณยู มีนาแก่กว่าเธอไม่ใช่เหรอ?"
L48_1.m_Talk_THA = L49_1
L49_1 = "Yoo Mina lớn hơn bạn phải không?"
L48_1.m_Talk_VTN = L49_1
L49_1 = "不是刘米娜小姐年纪更大一些吗？"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Ja. Miss Yoo Mina ist doch älter als du."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Mlle Yoo Mina est plus âgée que vous, non ?"
L48_1.m_Talk_FRA = L49_1
