L49_1.m_CharStrID = L50_1
L50_1 = "R"
L49_1.m_Pos = L50_1
L50_1 = "꼭 친언니만 언니라고 부르는 건 아니잖아요?"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "血のつながりがなくても、お姉ちゃんって呼んだりしますよね？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "And she doesn't have to be biologically related to you to be your big sister."
L49_1.m_Talk_ENG = L50_1
L50_1 = "又不是只有親姐姐才能叫姐姐對吧？"
L49_1.m_Talk_TWN = L50_1
L50_1 = "และการจะเป็นพี่สาวก็ไม่จำเป็นต้องมีความเกี่ยวข้องทางสายเลือดก็ได้"
L49_1.m_Talk_THA = L50_1
L50_1 = "Và cô ấy không nhất thiết phải có quan hệ huyết thống với bạn để trở thành chị gái của bạn."
L49_1.m_Talk_VTN = L50_1
L50_1 = "又不是只能管亲姐姐叫姐姐对吧？"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Und sie muss nicht mit dir verwandt sein, um deine große Schwester zu sein."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Et elle a pas besoin d'être de votre famille pour être votre grande sœur."
L49_1.m_Talk_FRA = L50_1
