L2_1.m_CutScenKey_Talk = L3_1
L2_1.m_CutScenProcessKey = 102
L2_1.m_CutScenID = 215
L2_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L2_1.m_bWaitClick = true
