L2_1.m_Face = "UNIT_HATE"
L3_1 = "YUMI_POLICE_NULL_NULL"
L2_1.m_CharStrID = L3_1
L3_1 = "L"
L2_1.m_Pos = L3_1
L2_1.m_Crash = 60
L3_1 = "언제 한 번 서로 찾아오세요!! 설렁탕 사드립니다! 설렁탕!!"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "お時間ある時に遊びにきてください！！　ラーメンおごります！　ラーメン！！"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Be sure to come by the station someday. I'll treat you to lunch! There's a good donut place I know!"
L2_1.m_Talk_ENG = L3_1
L3_1 = "改天來找我吧！我請你吃雪濃湯！雪濃湯！"
L2_1.m_Talk_TWN = L3_1
L3_1 = "อย่าลืมหาเวลามาที่สถานะล่ะ ฉันจะเลี้ยงข้าวคุณเอง ฉันรู้จักร้านโดนัทดีๆ นะ!"
L2_1.m_Talk_THA = L3_1
L3_1 = "Hôm nào ghé qua nhà ga nhé. Tôi sẽ đãi cậu bữa trưa! Tôi biết một chỗ bán bánh mỳ ngon lắm!"
L2_1.m_Talk_VTN = L3_1
L3_1 = "什么时候来找我吧！！我请你吃牛杂汤！牛杂汤！！"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Kommen Sie mich mal auf dem Revier besuchen. Dann lade ich Sie zum Essen ein. Ich kenne einen Laden mit guten Donuts!"
L2_1.m_Talk_DEU = L3_1
