L11_1.m_Face = "UNIT_SURPRISE"
L12_1 = "LEEMINSEO_FREEDOM_NULL_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "R"
L11_1.m_Pos = L12_1
L12_1 = "요, 요정님...... 이제 저희 인생에 모험 같은 건 없는 거겠죠......?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "よ、妖精様……ヒミコたちの人生に、これ以上の冒険はもうないですよね……？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "F-Fairy Godmother... There won't be another adventure in our lives, will there?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "精、精靈大人……我們的人生應該不會再有什麼冒險了吧……？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "นะ-นางฟ้าผู้พิทักษ์คะ... ชีวิตเราจะไม่ต้องเจอกับการผจญภัยแบบนี้อีกแล้วใช่ไหมคะ?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Mẹ Tiên Đỡ Đầu... Sẽ không có một cuộc phiêu lưu nào nữa trong cuộc đời chúng ta, phải không?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "精、精灵大人……现在我们的人生中应该不会再有什么冒险了吧……？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "G-Gute Fee … Es wird ab jetzt keine Abenteuer mehr geben, oder?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Ô marraine la bonne fée... Il n'y aura plus jamais une seule aventure dans notre vie, n'est-ce pas ?"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "EP5_ACT5_STAGE6_END@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
