L13_1 = "LEEMINSEO_FREEDOM_NULL_NULL"
L12_1.m_CharStrID = L13_1
L13_1 = "R"
L12_1.m_Pos = L13_1
L12_1.m_Crash = 30
L13_1 = "안전한 거겠죠? 그렇죠?"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "これからは安全ですよね？　そうですよね？"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Please tell us we can finally stay safe. Please."
L12_1.m_Talk_ENG = L13_1
L13_1 = "我們應該安全了吧？是這樣吧？"
L12_1.m_Talk_TWN = L13_1
L13_1 = "บอกทีว่าจากนี้ไปเราจะปลอดภัยกันแล้ว ขอร้องละ"
L12_1.m_Talk_THA = L13_1
L13_1 = "Xin hãy cho chúng tôi biết liệu cuối cùng chúng tôi có được an toàn không. Làm ơn."
L12_1.m_Talk_VTN = L13_1
L13_1 = "我们应该安全了吧？是这样吧？"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Bitte sag, dass wir jetzt endlich sicher sind. Bitte."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Dites-nous que nous sommes enfin en sécurité. S'il vous plaît."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
