L14_1 = "AKI_FREEDOM_NULL_NULL"
L13_1.m_CharStrID = L14_1
L14_1 = "L"
L13_1.m_Pos = L14_1
L13_1.m_Crash = 20
L14_1 = "다, 당연하죠! 뭘 물어보는 거에요, 민서 양!"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "と、当然です！　聞くまでもないですよ、ヒミコさん！"
L13_1.m_Talk_JPN = L14_1
L14_1 = "O-of course! It's obvious, Minseo!"
L13_1.m_Talk_ENG = L14_1
L14_1 = "當、當然啦！有什麼好問的呀，李旼序小姐！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "นะ-แน่นอน! ก็เห็นๆ กันอยู่นี่ มินซอ!"
L13_1.m_Talk_THA = L14_1
L14_1 = "T-tất nhiên! Quá rõ ràng rồi, Minseo!"
L13_1.m_Talk_VTN = L14_1
L14_1 = "当、当然啦！有什么好问的呀，亚子小姐！"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Na-Natürlich! Das ist doch selbstverständlich, Minseo!"
L13_1.m_Talk_DEU = L14_1
L14_1 = "B-Bien sûr ! C'est une évidence, Minseo !"
L13_1.m_Talk_FRA = L14_1
