L15_1 = "EP5_ACT5_STAGE6_END@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 215
L14_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "AKI_FREEDOM_NULL_NULL"
L14_1.m_CharStrID = L15_1
L15_1 = "L"
L14_1.m_Pos = L15_1
L15_1 = "요정 님도 양심이 있다면 우리 같은 소시민에게 더 이상의 시련을 내리진 않을 거라고요!"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "妖精様も良心があるなら、秋たちのような小市民にこれ以上の試練はお与えにならないはず！"
L14_1.m_Talk_JPN = L15_1
L15_1 = "The Fairy Godmother is merciful! She won't let us go through any more trouble if she has a conscience!"
L14_1.m_Talk_ENG = L15_1
L15_1 = "精靈大人有良心的話，就不可能再給我們這種小市民下達什麼試煉了啊！"
L14_1.m_Talk_TWN = L15_1
L15_1 = "นางฟ้าผู้พิทักษ์น่ะใจดีนะ! เธอจะไม่ปล่อยให้เราเจอปัญหาอีก ถ้าเธอยังมีสติ!"
L14_1.m_Talk_THA = L15_1
L15_1 = "Mẹ tiên đỡ đầu thật nhân từ! Bà ấy sẽ không để chúng ta phải trải qua bất kỳ rắc rối nào nữa nếu bà ấy còn có lương tâm!"
L14_1.m_Talk_VTN = L15_1
L15_1 = "精灵大人有良心的话，就不可能再给我们这种小市民下达什么试炼了啊！"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Die gute Fee ist gnädig! Wenn sie ein Gewissen hat, lässt sie uns nichts Schlimmes mehr durchmachen!"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Marraine la bonne fée est miséricordieuse. Si elle a une conscience, elle ne nous laissera pas traverser d'autres épreuves !"
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
