L18_1 = "UNIT_LAUGH"
L17_1.m_Face = L18_1
L18_1 = "CHLOE_COFFIN_NULL_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "C"
L17_1.m_Crash = 20
L18_1 = "이제 여러분에게 고난은 끝! 요정 님의 가호만이 충만할 뿐입니다!"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "皆さんの苦難はここまで！　これからは妖精様のご加護に満ちた日々が待ち受けています！"
L17_1.m_Talk_JPN = L18_1
L18_1 = "No hardships will come your way anymore. Your future path is filled with the grace of the Fairy Godmother!"
L17_1.m_Talk_ENG = L18_1
L18_1 = "現在各位的苦難已經結束了！大家都會受到精靈大人的加護！"
L17_1.m_Talk_TWN = L18_1
L18_1 = "จากนี้ไปพวกเธอจะไม่ต้องทำอะไรยากๆ แล้ว เส้นทางในอนาคตของพวกเธอจะเต็มไปด้วยพรจากนางฟ้าผู้พิทักษ์!"
L17_1.m_Talk_THA = L18_1
L18_1 = "Các bạn sẽ không phải chịu bất kỳ khó khăn nào nữa. Con đường tương lai của bạn sẽ tràn đầy ân huệ của Bà Tiên Đỡ Đầu!"
L17_1.m_Talk_VTN = L18_1
L18_1 = "现在各位的苦难已经结束了！大家都会受到精灵大人的庇护！"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Euch droht keinerlei Ungemach mehr. Euer zukünftiger Weg wird von der Gunst der guten Fee begleitet!"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Aucune embûche ne se présentera plus jamais sur votre chemin. Votre voie est pavée de la grâce de marraine la bonne fée."
L17_1.m_Talk_FRA = L18_1
