L21_1.m_Pos = L22_1
L22_1 = "가, 감사합니다 요정님! 감사합니다 요정님!"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "あ、ありがとうございます、妖精様！　感謝します、妖精様！"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Th-thank you, Fairy Godmother. Thank you!"
L21_1.m_Talk_ENG = L22_1
L22_1 = "非、非常感謝您，精靈大人！謝謝您，精靈大人！"
L21_1.m_Talk_TWN = L22_1
L22_1 = "ขะ-ขอบคุณค่ะ นางฟ้าผู้พิทักษ์ ขอบคุณ!"
L21_1.m_Talk_THA = L22_1
L22_1 = "C-cảm ơn bà, Bà Tiên Đỡ Đầu. Cảm ơn bà!"
L21_1.m_Talk_VTN = L22_1
L22_1 = "非、非常感谢！精灵大人！谢谢精灵大人！"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Da-Danke, gute Fee. Ich danke dir!"
L21_1.m_Talk_DEU = L22_1
L22_1 = "M-Merci, marraine la bonne fée. Merci !"
L21_1.m_Talk_FRA = L22_1
