L24_1 = "CHLOE_COFFIN_NULL_NULL"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "C"
L24_1 = "......이 재액 회피의 부적만 지니고 계신다면 말이죠."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "……この災厄回避のお守りさえあればですが。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "That's as long as you carry this anti-misfortune charm."
L23_1.m_Talk_ENG = L24_1
L24_1 = "……只要大家帶著這個避災的護身符就行了。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ตราบใดที่เธอพกเครื่องรางป้องกันโชคร้ายนี้"
L23_1.m_Talk_THA = L24_1
L24_1 = "Miễn là bạn mang theo lá bùa chống điềm gở này."
L23_1.m_Talk_VTN = L24_1
L24_1 = "……只要大家带着这个避灾的符咒就可以了。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Zumindest, solange ihr diesen Glücksbringer zum Schutz tragt."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Du moment que vous portez ce talisman anti-malheur."
L23_1.m_Talk_FRA = L24_1
