L28_1 = "EP5_ACT5_STAGE6_END@127#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 215
L27_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_Face = "UNIT_SURPRISE"
L28_1 = "AKI_FREEDOM_NULL_NULL"
L27_1.m_CharStrID = L28_1
L28_1 = "L"
L27_1.m_Pos = L28_1
L28_1 = "어...... 요, 요정 님의 신탁을 의심하는 건 아니지만...... 부적 값이 얼마나 될까요......?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "あ……よ、妖精様の信託を疑っているわけではないですが……お守りはおいくら位でしょうか……？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Um... It's not like I have doubts about what the Fairy Godmother is telling you, but... H-how much does it cost?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "呃……我、我不是懷疑精靈大人的神意，但是……這個護身符要多少錢啊？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "เอ่อ... ไม่ใช่ว่าฉันกังขาสิ่งที่นางฟ้าผู้พิทักษ์บอกเธอนะ แต่... มะ-มันราคาเท่าไหร่เหรอ?"
L27_1.m_Talk_THA = L28_1
L28_1 = "Ừm... Không phải tôi nghi ngờ về những gì Bà Tiên Đỡ Đầu đang nói với bạn, nhưng... N-nó có giá bao nhiêu?"
L27_1.m_Talk_VTN = L28_1
L28_1 = "啊……我、我不是怀疑精灵大人的神旨，但是……这个符咒多少钱啊？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Äh … Nicht, dass ich Zweifel an dem hätte, was die gute Fee sagt, aber … wie viel kostet das?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Hum... Ce n'est pas que je mette en doute ce que vous dit marraine la bonne fée, mais... c-combien ça coûte ?"
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
