L29_1 = "저, 저희가 요즘 재정상태가 조금 안 좋아서......"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "あ、秋たちの懐具合が最近思わしくなくて……"
L28_1.m_Talk_JPN = L29_1
L29_1 = "W-we're actually going through tough times financially..."
L28_1.m_Talk_ENG = L29_1
L29_1 = "因、因為我們最近的財政狀況不是很好……"
L28_1.m_Talk_TWN = L29_1
L29_1 = "อะ-อันที่จริงช่วงนี้เรากำลังมีปัญหาเรื่องการเงินน่ะ"
L28_1.m_Talk_THA = L29_1
L29_1 = "C-chúng t thực ra đang gặp khó khăn về tài chính..."
L28_1.m_Talk_VTN = L29_1
L29_1 = "因、因为我们最近财政状态不是很好……"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Wir sind knapp bei Kasse …"
L28_1.m_Talk_DEU = L29_1
L29_1 = "N-Nous traversons une période difficile financièrement parlant..."
L28_1.m_Talk_FRA = L29_1
