L35_1 = "UNIT_DESPAIR"
L34_1.m_Face = L35_1
L35_1 = "CHLOE_COFFIN_NULL_NULL"
L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "걱정 마세요! 요정 님의 가호를 받는 자매님들에게 무슨 돈을 받겠어요?"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "心配無用です！　妖精様のご加護を受ける方々からお金をとるわけないじゃないですか？"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Don't worry. You're all my sisters under the protective wings of the Fairy Godmother. How could I ever charge you money?"
L34_1.m_Talk_ENG = L35_1
L35_1 = "不用擔心！你們是受到精靈大人加護的姐妹們，我怎麼會收什麼錢呢？"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ไม่ต้องห่วง พวกเธอทุกคนคือน้องสาวที่อยู่ภายใต้การคุ้มครองของนางฟ้าผู้พิทักษ์ ฉันจะคิดเงินเธอได้ยังไง?"
L34_1.m_Talk_THA = L35_1
L35_1 = "Đừng lo lắng. Tất cả các bạn đều là chị em của tôi dưới đôi cánh bảo vệ của Bà Tiên Đỡ Đầu. Làm sao tôi có thể tính tiền bạn được chứ?"
L34_1.m_Talk_VTN = L35_1
L35_1 = "不用担心！各位姐妹们可是受到精灵大人庇护的，我怎么会收什么钱呢？"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Keine Bange. Ihr seid alle meine Schwestern unter den Fittichen der guten Fee. Wie könnte ich euch Geld abknöpfen?"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Ne vous inquiétez pas. Nous sommes toutes des sœurs sous les ailes protectrices de marraine la bonne fée. Comment pourrais-je vous faire payer quoi que ce soit ?"
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP5_ACT5_STAGE6_END@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 215
L35_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L36_1 = "UNIT_PRIDE"
L35_1.m_Face = L36_1
L36_1 = "CHLOE_COFFIN_NULL_NULL"
L35_1.m_CharStrID = L36_1
L35_1.m_Pos = "C"
L35_1.m_Crash = 30
L36_1 = "공짜에요 공짜! 이건 제 성의니까 꼭 몸에 지니고 계세요!"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "無料ですから、無料！　これは私の誠意ですから、ぜひ身に着けてください！"
L35_1.m_Talk_JPN = L36_1
L36_1 = "It's free! It's a gift from me. Make sure to carry it with you at all times!"
L35_1.m_Talk_ENG = L36_1
L36_1 = "這是免費的，免費！這是我的一片心意，請各位一定要帶在身上！"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ฟรีจ้ะ! เป็นของขวัญจากฉัน อย่าลืมพกติดตัวไว้ตลอดเวลานะ!"
L35_1.m_Talk_THA = L36_1
L36_1 = "Nó hoàn toàn miễn phí! Đây là một món quà từ tôi. Hãy nhớ luôn mang theo bên mình!"
L35_1.m_Talk_VTN = L36_1
L36_1 = "这是免费的呀！免费的！这是我的一片心意，请各位一定要带在身边！"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Es ist gratis! Ein Geschenk von mir! Tragt es nur immer bei euch!"
L35_1.m_Talk_DEU = L36_1
L36_1 = "C'est gratuit ! C'est un cadeau de ma part. Soyez sûres de le porter sur vous en permanence !"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
