L39_1 = "EP5_ACT5_STAGE6_END@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 215
L38_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L38_1.m_bWaitClick = true
