L38_1.m_Face = "UNIT_SURPRISE"
L39_1 = "AKI_FREEDOM_NULL_NULL"
L38_1.m_CharStrID = L39_1
L39_1 = "L"
L38_1.m_Pos = L39_1
L38_1.m_Crash = 30
L39_1 = "그, 그럴수가......! 정말 그냥 받아도 되는 건가요?!"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "そ、そんな……！　本当にタダでもらっていいんですか！？"
L38_1.m_Talk_JPN = L39_1
L39_1 = "R-really? You're just giving it to us?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "真、真的嗎……！我們真的可以這樣免費收下嗎？！"
L38_1.m_Talk_TWN = L39_1
L39_1 = "จะ-จริงเหรอ? จะยกให้เราเลยเหรอ?"
L38_1.m_Talk_THA = L39_1
L39_1 = "T-thật không? Bạn cứ thế đưa cho chúng tôi ư?"
L38_1.m_Talk_VTN = L39_1
L39_1 = "竟、竟然！真的可以这样免费收下吗？！"
L38_1.m_Talk_SCN = L39_1
L39_1 = "W-Wirklich? Du schenkst uns das einfach so?"
L38_1.m_Talk_DEU = L39_1
L39_1 = "V-Vraiment ? Vous nous le donnez ?"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "EP5_ACT5_STAGE6_END@139#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 215
L39_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L39_1.m_bWaitClick = true
