L40_1 = "UNIT_LAUGH"
L39_1.m_Face = L40_1
L40_1 = "LEEMINSEO_FREEDOM_NULL_NULL"
L39_1.m_CharStrID = L40_1
L40_1 = "R"
L39_1.m_Pos = L40_1
L39_1.m_Crash = 30
L40_1 = "이, 이런 친절을 받아본 건 엄마 말고 처음이에요...... 요정님!! 감사합니다!"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "こ、こんな親切、お母さん以外で初めてです……妖精様！！　ありがとうございます！"
L39_1.m_Talk_JPN = L40_1
L40_1 = "You're the kindest person I've ever met except my mom... Thank you, Fairy Godmother!"
L39_1.m_Talk_ENG = L40_1
L40_1 = "除、除了媽媽，還是第一次有人對我這麼好……精靈大人！！非常謝謝您！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "คุณเป็นคนใจดีที่สุดที่ฉันเคยเจอมาเลย นอกจากแม่ฉันนะ... ขอบคุณค่ะ นางฟ้าผู้พิทักษ์!"
L39_1.m_Talk_THA = L40_1
L40_1 = "Bà là người tốt nhất mà tôi từng gặp, trừ mẹ tôi... Cảm ơn bà, Bà Tiên Đỡ Đầu!"
L39_1.m_Talk_VTN = L40_1
L40_1 = "除、除了妈妈，还是第一次有人待我这么亲切……精灵大人！！谢谢！"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Du bist nach meiner Mutter die netteste Person, die ich kenne. Danke, gute Fee!"
L39_1.m_Talk_DEU = L40_1
L40_1 = "Vous êtes la personne la plus gentille que je connaisse, après ma maman... Merci, marraine la bonne fée !"
L39_1.m_Talk_FRA = L40_1
