L45_1 = "EP5_ACT5_STAGE6_END@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 215
L44_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L44_1.m_bWaitClick = true
