L45_1 = "UNIT_LAUGH"
L44_1.m_Face = L45_1
L45_1 = "LENA_COFFIN_NULL_NULL"
L44_1.m_CharStrID = L45_1
L45_1 = "R_M_I"
L44_1.m_Pos = L45_1
L45_1 = "얼레? 네가 웬일이래? 공짜로 부적을 다 써주고?"
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "へえ？　どういう風の吹き回しなの？　ただでお守りをあげるなんて？"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Huh? What's going on? You'd never give anything to anyone for free."
L44_1.m_Talk_ENG = L45_1
L45_1 = "咦？妳是怎麼了？竟然會免費發護身符？"
L44_1.m_Talk_TWN = L45_1
L45_1 = "หืม? เกิดอะไรขึ้น? ปกติไม่ให้ของใครฟรีๆ นี่"
L44_1.m_Talk_THA = L45_1
L45_1 = "Hử? Chuyện gì vậy? Bà sẽ không bao giờ cho không ai bất cứ thứ gì."
L44_1.m_Talk_VTN = L45_1
L45_1 = "啊呀？你怎么回事？竟然把符咒都免费送掉了？"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Nanu? Was ist los? Du verschenkst doch sonst nie etwas."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Hein ? Qu'est-ce qui se passe ? Tu ne donnes jamais rien à personne gratuitement."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
