L47_1 = "EP5_ACT5_STAGE6_END@146#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 146
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 215
L46_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_Face = "UNIT_SERIOUS"
L47_1 = "LENA_COFFIN_NULL_NULL"
L46_1.m_CharStrID = L47_1
L47_1 = "R"
L46_1.m_Pos = L47_1
L47_1 = "응? 그러고 보니 저거...... 지난 번에 자기 재액을 남한테 떠넘긴다는 부적 아니었어?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "え？　それって……この前の、自分の災難を他人に押し付けるためのお守りじゃない？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Hm? That thing... Isn't that a charm that you give to others to redirect the misfortunes meant for you?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "嗯？這麼一看，這個……不是上次把自己的災禍轉嫁給別人的護身符嗎?"
L46_1.m_Talk_TWN = L47_1
L47_1 = "หืม? อันนั้น... นั่นมันเครื่องรางที่เธอแจกให้คนอื่นๆ เพื่อไล่โชคร้ายออกไปจากตัวเธอไม่ใช่เหรอ?"
L46_1.m_Talk_THA = L47_1
L47_1 = "Hừm? Điều đó... Đó không phải là một lá bùa mà bà tặng cho người khác để chuyển đi những bất hạnh dành cho bạn sao?"
L46_1.m_Talk_VTN = L47_1
L47_1 = "嗯？这么一看，这……不是上次那个把自己的灾祸转移给别人的符咒吗?"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Hm? Dieser „Glücksbringer“ … den gibst du doch anderen, um Unheil, das für dich bestimmt ist, auf sie abzulenken?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "Hmm ? Ce machin... C'est pas le talisman que tu refiles aux autres pour diriger ta propre malchance vers eux ?"
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EP5_ACT5_STAGE6_END@147#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 147
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 215
L47_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "LENA_COFFIN_NULL_NULL"
L47_1.m_CharStrID = L48_1
L48_1 = "R"
L47_1.m_Pos = L48_1
L48_1 = "사장님 등판에 몰래 붙였다가 시말서 썼던......"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "社長の背中にこっそりつけたのがバレて、始末書を書かされたやつ……"
L47_1.m_Talk_JPN = L48_1
L48_1 = "You even wrote a letter of apology for putting it on Boss's back."
L47_1.m_Talk_ENG = L48_1
L48_1 = "妳還因為偷偷貼在老闆背後，寫了悔過書……"
L47_1.m_Talk_TWN = L48_1
L48_1 = "เธอยังเคยเขียนจดหมายขอโทษที่เคยเอามันไม่ติดหลังบอสเลย"
L47_1.m_Talk_THA = L48_1
L48_1 = "Bà thậm chí đã viết một lá thư xin lỗi vì đã đặt nó lên lưng Ông Chủ."
L47_1.m_Talk_VTN = L48_1
L48_1 = "你因为偷偷贴在老板背上还写了悔过书……"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Du hast doch sogar ein Entschuldigungsschreiben verfasst, weil du ihn dem Boss auf den Rücken geklebt hast."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Tu as même rédigé une lettre d'excuses après l'avoir collé dans le dos du patron."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "EP5_ACT5_STAGE6_END@148#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 148
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 215
L48_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L49_1 = "UNIT_LAUGH"
L48_1.m_Face = L49_1
L49_1 = "CHLOE_COFFIN_NULL_NULL"
L48_1.m_CharStrID = L49_1
L49_1 = "L"
L48_1.m_Pos = L49_1
L48_1.m_Crash = 60
L49_1 = "무, 무슨 말씀이시죠? 아하하! 하하하하!!"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "な、何のことでしょうね？　アハハ！　ハハハハ！！"
L48_1.m_Talk_JPN = L49_1
L49_1 = "I-I don't know what you're talking about. Hah hah! Hah hah Hah!"
L48_1.m_Talk_ENG = L49_1
L49_1 = "妳、妳在說什麼啊？啊哈哈！哈哈哈哈！！"
L48_1.m_Talk_TWN = L49_1
L49_1 = "พะ-พูดอะไรของเธอน่ะ ฮ่าๆ! ฮ่าๆๆ!"
L48_1.m_Talk_THA = L49_1
L49_1 = "T-tôi không biết bạn đang nói gì. Ha ha! Ha ha Ha!"
L48_1.m_Talk_VTN = L49_1
L49_1 = "您、您在说什么呀？啊哈哈！哈哈哈哈！！"
L48_1.m_Talk_SCN = L49_1
L49_1 = "I-Ich habe keine Ahnung, wovon du redest. Ha, ha! Ha, ha, ha!"
L48_1.m_Talk_DEU = L49_1
L49_1 = "J-Je ne vois pas de quoi tu parles. Ha ha ! Ha ha ha !"
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "EP5_ACT5_STAGE6_END@149#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 149
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 215
L49_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "CHLOE_COFFIN_NULL_NULL"
L49_1.m_CharStrID = L50_1
L50_1 = "L"
L49_1.m_Pos = L50_1
L49_1.m_Crash = 60
L50_1 = "호, 혹시 목 안 마르세요? 레나양?! 음료수 사드릴까요?!"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "の、のど乾かないですか！？　レナ？　何か飲み物、買ってきましょうか！？"
L49_1.m_Talk_JPN = L50_1
L50_1 = "A-aren't you thirsty, Lena? Do you want me to buy you something to drink?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "妳、妳會不會口渴呀？蕾娜小姐？！要我幫妳買飲料嗎？！"
L49_1.m_Talk_TWN = L50_1
L50_1 = "มะ-ไม่หิวน้ำเหรอเลน่า? อยากให้ฉันเลี้ยงเครื่องดื่มมั้ย?"
L49_1.m_Talk_THA = L50_1
L50_1 = "B-bạn không khát sao, Lena? Bạn có muốn tôi mua cho bạn đồ uống gì không?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "不、不知道你有没有口渴呀？蕾娜小姐？！要我给你买饮料吗？！"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Hast du nicht vielleicht Durst, Lena? Soll ich dir was zu trinken kaufen?"
L49_1.m_Talk_DEU = L50_1
L50_1 = "T-Tu n'as pas soif, Lena ? Tu veux que je t'offre quelque chose à boire ?"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
