L51_1 = "LENA_COFFIN_NULL_NULL"
L50_1.m_CharStrID = L51_1
L51_1 = "R"
L50_1.m_Pos = L51_1
L51_1 = "카페모카 프라푸치노 그란데 사이즈, 크림이랑 토핑 전부 가득 올려서 제일 비싼 걸로."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "カフェモカ・フラペチーノのグランデサイズね。ホイップやトッピングてんこ盛りで、一番高いやつ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Caffe Mocha frappucino, grande size, topped with all sorts of whipped cream goodness."
L50_1.m_Talk_ENG = L51_1
L51_1 = "我要咖啡摩卡星冰樂，最大杯，鮮奶油和配料全部加滿，要最貴的。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "คาฟเฟมอคค่าแฟรปปูชิโน แก้วใหญ่ โปะวิปครีมทุกชนิด"
L50_1.m_Talk_THA = L51_1
L51_1 = "Frappucino Caffe Mocha, cỡ lớn, phủ đầy đủ các loại kem đánh bông."
L50_1.m_Talk_VTN = L51_1
L51_1 = "我要摩卡星冰乐，最大杯，冰激凌和配料全部加满，要最贵的。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Einen großen Mocca frappucino mit reichlich Sahne obendrauf."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Un frappuccino mocha, en grande taille, avec une bonne dose de crème fouettée par-dessus."
L50_1.m_Talk_FRA = L51_1
