L4_1 = "EP5_ACT5_STAGE6_END@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 215
L3_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L3_1.m_bWaitClick = true
