L4_1 = "SEOYOON_REPLACER_NULL_LANCE"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L4_1 = "나도 고마워. 그리고 그동안 미안했어, 여러가지로."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "私もありがとう。それから、これまでごめんね、色々と。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "I want to thank you, too. And I'm sorry, for many things."
L3_1.m_Talk_ENG = L4_1
L4_1 = "我也得謝謝妳。還有，我要為這段時間的事情向妳道歉。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ฉันก็อยากขอบคุณเธอนะ และขอโทษสำหรับหลายๆ อย่าง"
L3_1.m_Talk_THA = L4_1
L4_1 = "Tôi cũng muốn cảm ơn bạn. Và tôi xin lỗi, vì nhiều điều."
L3_1.m_Talk_VTN = L4_1
L4_1 = "我也得谢谢你。还有，这段时间各种事情都很抱歉。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Auch ich möchte dir danken. Und mich entschuldigen. Für vieles."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Je voudrais te remercier également. Et m'excuser, pour bien des choses."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
