L6_1 = "EP5_ACT5_STAGE6_END@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 215
L5_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "SEOYOON_REPLACER_NULL_LANCE"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "C"
L6_1 = "네가 아니었으면 리플레이서를 쓰러트리고 우리 모두 자유를 되찾진 못했을 거야"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "あなたがいなかったら、リプレイサーを倒して私たち全員が自由を取り戻すことはできなかったと思う。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "We wouldn't have been able to defeat the Replacer Syndicate and regained our freedom without you."
L5_1.m_Talk_ENG = L6_1
L6_1 = "如果沒有妳，我們就無法打倒克隆集團，也無法重新討回自由。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "เราคงเอาชนะรีเพลสเซอร์ซินดิเคตและกอบกู้อิสรภาพได้ถ้าไม่มีเธอ"
L5_1.m_Talk_THA = L6_1
L6_1 = "Chúng tôi sẽ không thể đánh bại Nghiệp Đoàn Nhân Bản và lấy lại tự do nếu không có bạn."
L5_1.m_Talk_VTN = L6_1
L6_1 = "如果没有你，我们无法打倒克隆集团，也无法重新找回自由。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Ohne dich hätten wir das Replacer-Syndikat nicht besiegen können und unsere Freiheit nicht wiedererlangt."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Sans toi, on n'aurait pas pu vaincre le Syndicat des substituts et retrouver notre liberté."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "EP5_ACT5_STAGE6_END@156#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 156
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 215
L6_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "SEOYOON_REPLACER_NULL_LANCE"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L7_1 = "사과로 끝날 일은 아니겠지만...... 언젠가 빚을 갚을 날이 있겠지."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "ごめんで済む話ではないから……いつか借りを返す日が来るのでしょうね。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "I'm not trying to get away with just a word of apology. I'll make sure to repay you whenever I have the chance."
L6_1.m_Talk_ENG = L7_1
L7_1 = "雖然不是道歉就能了事的事情……但總有一天，我會還妳這個人情的。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ฉันไม่ได้พยายามจะขอโทษให้มันจบๆ ไปนะ ฉันจะตอบแทนเธอเมื่อมีโอกาส"
L6_1.m_Talk_THA = L7_1
L7_1 = "Tôi không cố gắng trốn đi chỉ với một lời xin lỗi. Tôi đảm bảo sẽ trả ơn bạn bất cứ khi nào tôi có cơ hội."
L6_1.m_Talk_VTN = L7_1
L7_1 = "虽然道歉是不够的……总有一天我能还上这个人情的。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Ich werde es nicht bei Worten der Entschuldigung belassen, sondern mich erkenntlich zeigen, wann immer sich mir die Gelegenheit bietet."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Je n'essaie pas de m'en tirer avec un simple mot d'excuse. Je ferai en sorte de te remercier dès que j'en aurai l'occasion."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
