L9_1 = "UNIT_PRIDE"
L8_1.m_Face = L9_1
L9_1 = "XIAOLIN_ALT_NULL_NULL"
L8_1.m_CharStrID = L9_1
L9_1 = "R"
L8_1.m_Pos = L9_1
L9_1 = "나도 동감이야. 자꾸 빚이 늘어나는 것 같긴 하지만."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "私も同感。どんどん借りが溜まっていくみたいだけど。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "I will, too. Although it feels we already have a big enough pile of debt."
L8_1.m_Talk_ENG = L9_1
L9_1 = "我也是這麼想。雖說人情好像越欠越多了。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "เช่นกัน แม้ว่าตอนนี้เราดูจะติดหนี้ท่วมหัวแล้วก็ตาม"
L8_1.m_Talk_THA = L9_1
L9_1 = "Tôi cũng vậy. Mặc dù có cảm giác chúng ta đã mắc một đống nợ."
L8_1.m_Talk_VTN = L9_1
L9_1 = "我也这么觉得。虽说人情好像越欠越大了。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ich auch. Obwohl es sich anfühlt, als sei unser Schuldenberg schon hoch genug."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Moi aussi. Même si j'ai l'impression qu'on a déjà un gros paquet de dettes envers toi."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "EP5_ACT5_STAGE6_END@159#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 159
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 215
L9_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
