L10_1 = "YOOJIN_ALT_NULL_NULL"
L9_1.m_CharStrID = L10_1
L10_1 = "L"
L9_1.m_Pos = L10_1
L10_1 = "나, 나도...... 고맙다고 해 둘게. 일단은 말이지."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "お、俺も……礼を言っておくぜ。とりあえず、な。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "M-me too! Th-thank you. For now."
L9_1.m_Talk_ENG = L10_1
L10_1 = "我、我也……姑且謝謝妳吧。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ฉะ-ฉันด้วย! ขะ-ขอบใจนะ สำหรับตอนนี้"
L9_1.m_Talk_THA = L10_1
L10_1 = "T-tôi cũng vậy! Bây giờ. C-cám ơn."
L9_1.m_Talk_VTN = L10_1
L10_1 = "我、我也……总之，和你说声谢谢吧。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "I-Ich auch! Da-Danke. Fürs Erste."
L9_1.m_Talk_DEU = L10_1
L10_1 = "M-Moi aussi ! M-Merci. Pour le moment."
L9_1.m_Talk_FRA = L10_1
