L11_1 = "KIMSOBIN_ALT_NULL_NULL"
L10_1.m_CharStrID = L11_1
L11_1 = "R"
L10_1.m_Pos = L11_1
L11_1 = "유, 유진아...... 왜 옆을 보고 말하는 거야?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "シ、シロコ……どうしてそっぽ向いて言うの？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "E-Eujin, you're looking at the wrong direction..."
L10_1.m_Talk_ENG = L11_1
L11_1 = "劉、劉珍……為什麼妳要看著旁邊說話啊？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "ยะ-ยูจิน เธอมองผิดทางแล้วนะ..."
L10_1.m_Talk_THA = L11_1
L11_1 = "E-Eujin, bạn đang nhìn sai hướng..."
L10_1.m_Talk_VTN = L11_1
L11_1 = "刘、刘珍……为什么看着旁边说话啊？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Eu-Eujin, du siehst in die falsche Richtung …"
L10_1.m_Talk_DEU = L11_1
L11_1 = "E-Eujin, tu regardes dans la mauvaise direction."
L10_1.m_Talk_FRA = L11_1
