L14_1.m_Pos = "C"
L15_1 = "......나 혼자 한 일이 아니야. 오히려 내가 감사해야......"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "……私ひとりで成し遂げたことじゃないから。むしろ、私のほうからお礼を言わないと……"
L14_1.m_Talk_JPN = L15_1
L15_1 = "I didn't do it alone. I should be thanking all of you..."
L14_1.m_Talk_ENG = L15_1
L15_1 = "……這些事不是我一個人完成的。反而是我得向你們道謝……"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ฉันไม่ได้ทำคนเดียวนะ ฉันควรจะขอบคุณพวกเธอทุกคนด้วย..."
L14_1.m_Talk_THA = L15_1
L15_1 = "Tôi đã không làm việc đó một mình. Tôi nên cảm ơn tất cả các bạn..."
L14_1.m_Talk_VTN = L15_1
L15_1 = "……这些事不是我一个人完成的。反而是我得向你们道谢……"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Ich habe es ja nicht allein geschafft. Ich sollte euch allen danken …"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Je n'ai rien fait toute seule. C'est moi qui devrais tous vous remercier..."
L14_1.m_Talk_FRA = L15_1
