L26_1.m_CharStrID = L27_1
L27_1 = "R"
L26_1.m_Pos = L27_1
L26_1.m_Crash = 60
L27_1 = "남의 함선 냉장고를 발로 차고 다니면 어쩌자는 거에요?!"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "他所の艦船の冷蔵庫を蹴るなんて！？"
L26_1.m_Talk_JPN = L27_1
L27_1 = "You can't go around kicking fridges in someone else's ship!"
L26_1.m_Talk_ENG = L27_1
L27_1 = "踢別人艦船裡的冰箱是想幹嘛啊？！"
L26_1.m_Talk_TWN = L27_1
L27_1 = "จะเที่ยวเตะตู้เย็นบนยานของคนอื่นไม่ได้นะ!"
L26_1.m_Talk_THA = L27_1
L27_1 = "Bạn không thể cứ mải việc lùng sục tủ lạnh trong tàu của người khác!"
L26_1.m_Talk_VTN = L27_1
L27_1 = "用脚踹别人的舰船冷藏库是想干嘛啊？！"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Du kannst nicht einfach gegen Kühlschränke auf fremden Schiffen treten!"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Vous ne pouvez pas vous promener en donnant des coups de pied dans les frigos du vaisseau comme ça !"
L26_1.m_Talk_FRA = L27_1
