L28_1 = "UNIT_DESPAIR"
L27_1.m_Face = L28_1
L28_1 = "CHARLIE_RSEVEN_NULL_NULL"
L27_1.m_CharStrID = L28_1
L28_1 = "L"
L27_1.m_Pos = L28_1
L27_1.m_Crash = 20
L28_1 = "아, 그게...... 우리 일행이 단 걸 좋아해서......"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "あ、実は……仲間が大の甘党でな……"
L27_1.m_Talk_JPN = L28_1
L28_1 = "I-it's just that one of us likes sweet stuff very much, so..."
L27_1.m_Talk_ENG = L28_1
L28_1 = "啊，那個……因為我們都喜歡甜食……"
L27_1.m_Talk_TWN = L28_1
L28_1 = "พะ-พอดีว่าพวกเราคนหนึ่งชอบของหวานมากน่ะ..."
L27_1.m_Talk_THA = L28_1
L28_1 = "C-chỉ là ai trong chúng ta cũng rất thích đồ ngọt, nên..."
L27_1.m_Talk_VTN = L28_1
L28_1 = "啊，那个……因为我们都喜欢甜食……"
L27_1.m_Talk_SCN = L28_1
L28_1 = "N-Na ja, eine von uns fährt halt voll auf Süßes ab, daher …"
L27_1.m_Talk_DEU = L28_1
L28_1 = "C-C'est juste qu'y en a une parmi nous qui aime vraiment les trucs sucrés, alors..."
L27_1.m_Talk_FRA = L28_1
