L29_1 = "EP5_ACT5_STAGE6_END@178#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 178
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 215
L28_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "KIMHANA_COFFIN_NULL_NULL"
L28_1.m_CharStrID = L29_1
L29_1 = "R"
L28_1.m_Pos = L29_1
L28_1.m_Crash = 60
L29_1 = "그걸 지금 말이라고 해요?! 단걸 좋아하면 편의점이나 가 보라고!!"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "冗談で言ってるんですか！？　甘党なら、コンビニにでも行ってください！！"
L28_1.m_Talk_JPN = L29_1
L29_1 = "What kind of excuse is that? Go find a convenience store if you're looking for sweets!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "你這樣說像話嗎？！喜歡甜食的話就去便利商店啊！！"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ข้ออ้างอะไรเนี่ย? ถ้าอยากได้ของหวานก็ไปหาร้านสะดวกซื้อซะ!"
L28_1.m_Talk_THA = L29_1
L29_1 = "Viện cớ gì thế? Hãy tìm cửa hàng tiện lợi nếu bạn muốn đồ ngọt!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "你说的这像话吗？！喜欢甜食的话就去便利店啊！！"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Na und? Wenn du Süßigkeiten willst, kauf sie im Supermarkt!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Ce n'est pas une excuse ! Allez-donc dans un magasin si vous cherchez des bonbons !"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "EP5_ACT5_STAGE6_END@179#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 179
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 215
L29_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_SERIOUS"
L30_1 = "KIMHANA_COFFIN_NULL_NULL"
L29_1.m_CharStrID = L30_1
L30_1 = "R"
L29_1.m_Pos = L30_1
L29_1.m_Crash = 60
L30_1 = "이거 다 어떡할 거야?! 배상해요옷!!"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "これどうするんですか！？　弁償ですよっ！！"
L29_1.m_Talk_JPN = L30_1
L30_1 = "What are you going to do about this mess? You'll have to pay for it!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "你們這是想怎麼辦？！賠錢啊啊！！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "คุณจะทำยังไงกับของพวกนี้? คุณต้องชดใช้นะ!"
L29_1.m_Talk_THA = L30_1
L30_1 = "Bạn sẽ làm gì với mớ hỗn độn này? Bạn sẽ phải tự mình chi trả hết!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "这些可怎么办啊？！赔钱啊啊！！"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Was gedenkst du, jetzt zu tun? Das wirst du bezahlen müssen!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Qu'est-ce que vous comptez faire de tout ce bazar ? Vous allez devoir payer pour ça !"
L29_1.m_Talk_FRA = L30_1
