L31_1 = "EP5_ACT5_STAGE6_END@180#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 180
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 215
L30_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "CHARLIE_RSEVEN_NULL_NULL"
L30_1.m_CharStrID = L31_1
L31_1 = "L"
L30_1.m_Pos = L31_1
L31_1 = "어...... 우리가 가진 돈은 리플레이서와 싸우느라 다 불태워 버려서......"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "えっと……俺たちの持ち金はリプレイサーと戦う途中、全部燃えてしまって……"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Um... We spent all our money on the war against the Replacers..."
L30_1.m_Talk_ENG = L31_1
L31_1 = "呃……我們帶的錢都在和克隆集團的戰鬥中燒掉了……"
L30_1.m_Talk_TWN = L31_1
L31_1 = "เอ่อ.. เราใช้เงินไปกับการทำสงครามกับรีเพลสเซอร์หมดแล้ว"
L30_1.m_Talk_THA = L31_1
L31_1 = "Ừm... Chúng tôi đã tiêu hết tiền vào cuộc chiến chống lại Người Nhân Bản..."
L30_1.m_Talk_VTN = L31_1
L31_1 = "啊……我们带的钱都因为和克隆集团的战斗烧掉了……"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Äh … unser ganzes Geld ist für den Kampf gegen die Replacer draufgegangen."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Hum... On a dépensé tout notre argent dans la guerre contre les substituts..."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
