L32_1 = "UNIT_LAUGH"
L31_1.m_Face = L32_1
L32_1 = "CHARLIE_RSEVEN_NULL_NULL"
L31_1.m_CharStrID = L32_1
L32_1 = "L"
L31_1.m_Pos = L32_1
L32_1 = "아, 혹시 몸으로 때우면 안될까?"
