L31_1.m_fTalkTime = 0.03
L32_1 = "あ、体は張れるけどな？"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Can't we work it off instead?"
L31_1.m_Talk_ENG = L32_1
L32_1 = "啊，不能用身體來償還嗎？"
L31_1.m_Talk_TWN = L32_1
L32_1 = "เราทำงานชดใช้แทนได้ไหม?"
L31_1.m_Talk_THA = L32_1
L32_1 = "Thay vào đó sao chúng ta cùng nhau giải quyết?"
L31_1.m_Talk_VTN = L32_1
L32_1 = "啊，不能用人身偿还吗？"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Können wir es nicht irgendwie abarbeiten?"
L31_1.m_Talk_DEU = L32_1
L32_1 = "On peut pas trouver un arrangement plutôt ?"
L31_1.m_Talk_FRA = L32_1
