L35_1 = "그...... 제가 이런 말 하긴 그렇지만 아무래도 그건 별로 안 좋은 생각인 것 같은데......"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "あの……言いにくいのですが、それはあまりよろしくない発想かと……"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Erm... It might be awkward coming from me, but I don't think that's a very good idea..."
L34_1.m_Talk_ENG = L35_1
L35_1 = "這……雖然我來說這些有點尷尬，但我覺得這不是什麼好主意……"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เอ่อ... ให้ฉันเป็นคนพูดเองอาจจะฟังดูแปลกๆ นะ แต่ฉันว่านั่นไม่ใช่ความคิดที่ดีเท่าไหร่..."
L34_1.m_Talk_THA = L35_1
L35_1 = "Ờm... Tôi có thể cảm thấy hơi khó xử, nhưng tôi không nghĩ đó là một ý kiến ​​hay..."
L34_1.m_Talk_VTN = L35_1
