L34_1.m_Talk_SCN = L35_1
L35_1 = "Ähm … Ich sollte das vielleicht nicht sagen, aber ich halte das für keine gute Idee."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Hum... C'est peut-être maladroit de ma part, mais je ne pense pas que ce soit une très bonne idée..."
