L40_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "C"
L40_1 = "우리 코핀 컴퍼니의 계약서에 도장을 찍을 생각을 하다니 그 용기가 가상하군요."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "我がコフィンカンパニーの契約書にサインするなんて、素晴らしい勇気です。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "You're mighty brave to think of signing a contract with the Coffin Company."
L39_1.m_Talk_ENG = L40_1
L40_1 = "竟然想要在我們科芬公司的契約書上蓋章，真是勇氣可嘉。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "กล้ามากนะที่คิดเซ็นสัญญากับบริษัทคอฟฟิน"
L39_1.m_Talk_THA = L40_1
L40_1 = "Bạn thật dũng cảm khi nghĩ đến việc ký hợp đồng với Công Ty Coffin."
L39_1.m_Talk_VTN = L40_1
L40_1 = "竟然想与我们科芬公司签约，我很欣赏你的勇气。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Ganz schön mutig, einen Vertrag bei der Coffin Company unterschreiben zu wollen."
L39_1.m_Talk_DEU = L40_1
L40_1 = "C'est très courageux de vouloir signer un contrat avec la Compagnie Coffin."
L39_1.m_Talk_FRA = L40_1
