L41_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "C"
L41_1 = "참고로 채무 변제가 완료될 때까지는 최저시급만 지급될 테니 노력 분발하시길 바랍니다."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "ちなみに、完済するまでは最低賃金のみ支給されますので、精いっぱい頑張ってくださいね。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "But remember, you'll only be paid minimum wage until you pay off your debt."
L40_1.m_Talk_ENG = L41_1
L41_1 = "順帶一提，直到你們的債務還清為止，我們都只會支付最低薪資，所以請你們奮發圖強吧。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "จำไว้นะว่าคุณจะได้รับค่าแรงขั้นต่ำจนกว่าจะจ่ายหนี้หมด"
L40_1.m_Talk_THA = L41_1
L41_1 = "Nhưng hãy nhớ bạn sẽ chỉ được trả lương tối thiểu cho đến khi bạn trả hết nợ."
L40_1.m_Talk_VTN = L41_1
L41_1 = "顺便说一句，直到本公司还清债务为止，我们都只会支付最低时薪，所以请奋发图强吧。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Denk aber daran, dass du nur den Mindestlohn bekommst, bis deine Schulden abbezahlt sind."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Mais rappelez-vous, vous tournerez au minimum légal jusqu'à ce que vos dettes soient remboursées."
L40_1.m_Talk_FRA = L41_1
