L43_1.m_Pos = "C"
L44_1 = "사장님? 여기까지 직접 온 거야? 위험했을 텐데......"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "社長？　わざわざここまで来たの？　危ないと思うけど……"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Boss? You came all the way here? It might have been dangerous."
L43_1.m_Talk_ENG = L44_1
L44_1 = "老闆？你親自到這裡來了嗎？明明很危險……"
L43_1.m_Talk_TWN = L44_1
L44_1 = "บอสคะ? มาถึงนี่เลยเหรอ? อาจเป็นอันตรายได้นะคะ"
L43_1.m_Talk_THA = L44_1
L44_1 = "Ông Chủ? Bạn đã đến tận đây? Có thể nguy hiểm đấy."
L43_1.m_Talk_VTN = L44_1
