L47_1 = "UNIT_PRIDE"
L46_1.m_Face = L47_1
L47_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L46_1.m_CharStrID = L47_1
L47_1 = "R_M_I"
L46_1.m_Pos = L47_1
L47_1 = "물론이네. 애초에 내가 입안한 계획이니까 문제가 생기지 않도록 직접 확인해야 하지 않겠나?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "もちろんさ、元々私が立てた計画なのだ。問題が生じないように、直接確認しないと。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Of course I did. It's a plan that I devised myself. It's only right that I make sure everything's working out."
L46_1.m_Talk_ENG = L47_1
L47_1 = "當然了。這個計畫本來就是我立案的，我當然得來親自確認有沒有什麼問題吧？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "แน่นอน นี่เป็นแผนที่ผมออกแบบเองนะ ผมก็ต้องทำให้ทุกอย่างราบรื่นสิ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Tất nhiên là tôi đã đến. Đó là một kế hoạch do chính tôi nghĩ ra. Chỉ tôi mới đảm bảo được rằng mọi thứ đang diễn ra tốt đẹp."
L46_1.m_Talk_VTN = L47_1
L47_1 = "当然了。这个计划一开始就是我确立的，我当然得来亲自确认一下计划有没有问题对吧？"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Natürlich bin ich hergekommen. Schließlich stammt der Plan von mir. Da ist es nur recht und billig, dass ich darauf achte, dass er auch aufgeht."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Évidemment que je suis venu. C'est un plan que j'avais élaboré moi-même. Il est bien normal que je sois venu m'assurer que tout fonctionnait parfaitement."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EP5_ACT5_STAGE6_END@197#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 197
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 215
L47_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "UNIT_LAUGH"
L47_1.m_Face = L48_1
L47_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L48_1 = "L"
L47_1.m_Pos = L48_1
L48_1 = "생각보다 책임감 있는 모습이네. 다시 봤어, 사장님."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "思ったよりも責任感があるんだね。見直したよ、社長。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "You're a much more responsible leader than I thought. Impressive."
L47_1.m_Talk_ENG = L48_1
L48_1 = "你比我想像得還要有責任感呢。我對你刮目相看了，老闆。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "คุณเป็นหัวหน้าที่รับผิดชอบมากกว่าที่ฉันคิดไว้เยอะเลย น่าประทับใจจริงๆ"
L47_1.m_Talk_THA = L48_1
L48_1 = "Bạn là một thủ lĩnh có trách nhiệm hơn tôi nghĩ. Thật ấn tượng."
L47_1.m_Talk_VTN = L48_1
L48_1 = "你看起来比我想象的还要有责任心呢。令人刮目相看啊，老板。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Sie sind ein wesentlich verantwortungsvollerer Anführer, als ich dachte."
L47_1.m_Talk_DEU = L48_1
L48_1 = "Vous êtes un dirigeant bien plus responsable que je ne le pensais. Impressionnant."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
