L50_1 = "EP5_ACT5_STAGE6_END@199#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 199
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 215
L49_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "UNIT_LAUGH"
L49_1.m_Face = L50_1
L50_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "C"
L50_1 = "미나 양도 참 주변에 어지간히 신경 안 쓰시는 타입이시네요."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "ミナさんって、本当にまわりのこと気にしないタイプなんですね。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "You don't really listen to rumors, do you, Mina?"
L49_1.m_Talk_ENG = L50_1
L50_1 = "米娜小姐也是那種不怎麼在意周圍情況的類型呢。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "เธอไม่ฟังข่าวลือเลยสินะ มีนา?"
L49_1.m_Talk_THA = L50_1
L50_1 = "Bạn không thực sự nghe những lời đồn đại, phải không Mina?"
L49_1.m_Talk_VTN = L50_1
L50_1 = "看来米娜小姐也是那种不怎么在意周围的类型呢。"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Gib nicht so viel auf die Gerüchte, Mina."
L49_1.m_Talk_DEU = L50_1
L50_1 = "On dirait que tu n'écoutes pas trop ce qui se dit, Mina, je me trompe ?"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
L51_1 = "EP5_ACT5_STAGE6_END@200#Talk"
L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 200
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 215
L50_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L50_1.m_bWaitClick = true
L50_1.m_fWaitTime = 0
L51_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "C"
L51_1 = "사장님은 원래부터 이것저것 알게 모르게 잘 챙겨주신다고 사원들 사이에서 평가가 좋은 편입니다."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "元々社長は面倒見が良いって、社員の間で評判が良いんですよ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "Boss has always been known for providing a generous amount of overt and covert care and support for our staff."
L50_1.m_Talk_ENG = L51_1
L51_1 = "老闆都會默默地在各種事情上照顧別人，所以員工們對老闆的評價很高。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "บอสขึ้นชื่อเรื่องการดูแลและสนับสนุนพนักงานของเราทั้งแบบเปิดเผยและไม่เปิดเผยมาตลอด"
L50_1.m_Talk_THA = L51_1
L51_1 = "Ông Chủ nổi tiếng là người luôn quan tâm và hỗ trợ nhân viên, dù là công khai hay bí mật."
L50_1.m_Talk_VTN = L51_1
L51_1 = "老板在各种事情上都默默照顾别人，所以员工们对老板的评价也很高。"
L50_1.m_Talk_SCN = L51_1
L51_1 = "Der Boss hat sein Personal schon immer auf vielfältige Weise unterstützt, mal offen, mal im Verborgenen."
L50_1.m_Talk_DEU = L51_1
L51_1 = "Le patron a toujours été connu pour fournir un généreux soutien, officiel ou non, à tout le personnel."
L50_1.m_Talk_FRA = L51_1
