L2_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L1_1.m_CharStrID = L2_1
L1_1.m_Pos = "C"
L2_1 = "저와는 달리 좀 괴짜 같다는 평도 있긴 하지만요."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "僕とは違って、ちょっと変わり者っぽいという評価もありますけどね。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Although some might accuse Boss of being eccentric, unlike me."
L1_1.m_Talk_ENG = L2_1
L2_1 = "雖說也有人與我不一樣，覺得老闆有點古怪。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "แม้ว่าบางคนอาจกล่าวหาว่าบอสเป็นคนแปลกๆ ไม่เหมือนผม"
L1_1.m_Talk_THA = L2_1
L2_1 = "Mặc dù một số người có thể cho rằng Ông Chủ là người lập dị, không giống như tôi."
L1_1.m_Talk_VTN = L2_1
L2_1 = "虽说也有人与我不一样，觉得老板有点古怪。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "Auch wenn ihn einige im Gegensatz zu mir als exzentrisch bezeichnen."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Certains l'accusent aussi d'être excentrique, mais pas moi."
L1_1.m_Talk_FRA = L2_1
