L6_1 = "EP5_ACT5_STAGE6_END@205#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 205
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 215
L5_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "UNIT_LAUGH"
L5_1.m_Face = L6_1
L6_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L5_1.m_CharStrID = L6_1
L6_1 = "R"
L5_1.m_Pos = L6_1
L6_1 = "하하핫! 시윤 군, 자네도 사회생활 능력이 많이 늘었군. 혹시 연봉인상이 필요하지 않나?"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "ハハハッ！　アキヤマ君、君も処世術に長けてきたな。\nひょっとして、年俸引き上げが必要なタイミングか？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Hah hah! Your social skills have improved a lot, Shiyoon. Don't you need a higher salary?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "哈哈哈！時雲君，你的社會生活能力也增長很多呢。也許你該漲漲年薪了吧？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "ฮ่าๆ! ทักษะการเข้าสังคมของคุณดีขึ้นมากนะ ไม่อยากได้เงินเดือนสูงขึ้นเหรอ?"
L5_1.m_Talk_THA = L6_1
L6_1 = "Ha ha! Kỹ năng xã hội của bạn đã được cải thiện rất nhiều, Shiyoon. Bạn không cần mức lương cao hơn sao?"
L5_1.m_Talk_VTN = L6_1
L6_1 = "哈哈哈！周时云，你的社会生活能力也见长不少啊。也许你需要涨涨年薪啊？"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Ha, ha! Ihre Sozialkompetenz hat sich stark verbessert, Shiyoon. Sie hoffen wohl auf eine Gehaltserhöhung?"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Ha ha ! Vos compétences sociales se sont grandement améliorées, Charles. Souhaitez-vous un salaire plus élevé ?"
L5_1.m_Talk_FRA = L6_1
