L8_1 = "EP5_ACT5_STAGE6_END@207#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 207
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 215
L7_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "UNIT_LAUGH"
L7_1.m_Face = L8_1
L8_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "C"
L8_1 = "어이쿠, 저야 그저 사장님 인품에 감명 받아서 솔직하게 이야기 했을 뿐인 걸요."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "そんなそんな、僕はただ、社長のお人柄に感銘を受けて正直に話しただけですよ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Whoa, I was just telling her my honest thoughts about how I was genuinely impressed by your generous character."
L7_1.m_Talk_ENG = L8_1
L8_1 = "哎呀，我也只是對老闆的人品有些感觸，誠實地說出來而已呀。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "โห ผมแค่บอกความจริงกับเธอว่าผมประทับใจในอุปนิสัยเอื้อเฟื้อของคุณแค่ไหนเองครับ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Ồ, tôi chỉ đang chia sẻ với cô ấy những suy nghĩ trung thực của mình về việc tôi thực sự ấn tượng với tính cách hào phóng của bạn."
L7_1.m_Talk_VTN = L8_1
L8_1 = "哎呀，我也只是对老板的人品有些感触，所以诚实地说出来而已呀。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Nein, ich habe nur meine ehrliche Meinung über Ihre Großzügigkeit gesagt."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Oh, je n'ai fait que lui exprimer le fait que j'étais sincèrement impressionné par votre nature généreuse."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "EP5_ACT5_STAGE6_END@208#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 208
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 215
L8_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L9_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L8_1.m_CharStrID = L9_1
L8_1.m_Pos = "C"
L9_1 = "하지만 챙겨주신다면야 고맙게 받도록 하겠습니다."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "でも、もしお考え頂けるようでしたら、お言葉に甘えたく。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "But it'd be rude of me to decline an offer from my superior, wouldn't it?"
L8_1.m_Talk_ENG = L9_1
L9_1 = "但如果您這麼照顧我，我就心存感激地收下了。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "แต่ถ้าจะปฏิเสธข้อเสนอจากผู้บังคับบัญชาก็จะไม่สุภาพใช่ไหมครับ?"
L8_1.m_Talk_THA = L9_1
L9_1 = "Nhưng sẽ thật thô lỗ nếu từ chối lời đề nghị từ cấp trên, phải không?"
L8_1.m_Talk_VTN = L9_1
L9_1 = "不过您如果这么照顾我，我就感激地收下了。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Aber es wäre natürlich unhöflich von mir, ein Angebot eines Vorgesetzten abzulehnen, nicht wahr?"
L8_1.m_Talk_DEU = L9_1
L9_1 = "Mais ce serait malpoli de ma part de refuser une offre de mon supérieur, n'est-ce pas ?"
L8_1.m_Talk_FRA = L9_1
