L11_1.m_Pos = L12_1
L12_1 = "흘려 넘길 수 없는 말들이 돌아다니고 있는 것 같군요. 뭘 인상하신다고요?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "これは聞き流せないですね、何を引き上げると？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "I can't seem to ignore all these words I'm hearing. A raise?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "你們好像在聊什麼不能裝作沒聽到的話題呢。您說漲什麼？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "ฉันมองข้ามคำที่ฉันได้ยินไม่ได้เลย ขึ้นเงินเดือนเหรอ?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Tôi dường như không thể bỏ qua những lời tôi đang nghe. Tăng lương ư?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "你们好像在聊什么不能错过的话题呢。您说涨什么？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Welch liebliches Wort in meinen Ohren. Eine Gehaltserhöhung?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Je n'ai pas pu m'empêcher d'entendre votre conversation. Une augmentation ?"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
