L15_1 = "YUMI_POLICE_NULL_NULL"
L14_1.m_CharStrID = L15_1
L15_1 = "R_M_I"
L14_1.m_Pos = L15_1
L15_1 = "사장님......? 정말 사장님이라고요?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "社長……？　本当に社長なんですか？"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Boss? Are you the president?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "老闆？真的是老闆嗎？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "บอส? คุณคือประธานเหรอ?"
L14_1.m_Talk_THA = L15_1
L15_1 = "Ông chủ? Bạn có phải là chủ tịch không?"
L14_1.m_Talk_VTN = L15_1
L15_1 = "老板？真的是老板吗？"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Boss? Sind Sie der Vorsitzende?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Patron ? Vous êtes le directeur ?"
L14_1.m_Talk_FRA = L15_1
