L16_1 = "UNIT_LAUGH"
L15_1.m_Face = L16_1
L16_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L15_1.m_CharStrID = L16_1
L16_1 = "L"
L15_1.m_Pos = L16_1
L16_1 = "그렇다네! 이 코핀 컴퍼니의 지배자이자 최고 존엄! 머신 갑이라고 하네."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "そうだ！　このコフィンカンパニーの支配者であり、最高指導者のマシーン-甲-だ。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "I am. I'm the supreme ruler and the head honcho of the Coffin Company, Machine G.A.P."
L15_1.m_Talk_ENG = L16_1
L16_1 = "沒錯！我就是科芬公司的支配者以及最高尊嚴！機械．我超帥~。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ใช่แล้ว ฉันคือผู้บริหารสูงสุดและนักล่าคนเก่งแห่งบริษัทคอฟฟิน แมชชีน G.A.P."
L15_1.m_Talk_THA = L16_1
L16_1 = "Đúng thế. Tôi là người lãnh đạo tối cao và là người đứng đầu Công Ty Coffin, G.A.P. Máy ạ."
L15_1.m_Talk_VTN = L16_1
L16_1 = "没错！我就是科芬公司的支配者以及最高尊严！我叫G·A·P。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Ja. Ich bin Machine G.A.P, Chef und Herrscher der Coffin Company."
L15_1.m_Talk_DEU = L16_1
L16_1 = "En effet. Je suis le chef suprême et le grand manitou de la Compagnie Coffin, Machine G.A.P."
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "EP5_ACT5_STAGE6_END@216#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 216
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 215
L16_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Face = "UNIT_IDLE"
L17_1 = "YUMI_POLICE_NULL_NULL"
L16_1.m_CharStrID = L17_1
L17_1 = "R"
L16_1.m_Pos = L17_1
L17_1 = "아, 네 그렇군요...... 그 동안 공무에 협조해 주셔서 감사합니다."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "あ、そうなんですね……これまで公務にご協力頂き、ありがとうございました。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Ah, I see. We, the police, appreciate the cooperation you've provided us with all along."
L16_1.m_Talk_ENG = L17_1
L17_1 = "啊，是這樣啊……非常感謝您這段時間協助我們執行公務。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "เข้าใจแล้วละ ตำรวจอย่างพวกเราขอบคุณที่ให้ความร่วมมือกับเรามาตลอดนะคะ"
L16_1.m_Talk_THA = L17_1
L17_1 = "À, tôi hiểu rồi. Chúng tôi, những cảnh sát, đánh giá cao sự hợp tác của bạn với chúng tôi trong suốt thời gian qua."
L16_1.m_Talk_VTN = L17_1
L17_1 = "啊，好的，这样啊……感谢您这段时间协助我们的公务。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Ah, verstehe. Wir von der Polizei schätzen die Zusammenarbeit mit Ihnen schon seit vielen Jahren."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Ah, je vois. Nous, à la police, apprécions votre coopération depuis le début."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
L18_1 = "EP5_ACT5_STAGE6_END@217#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 217
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 215
L17_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_IDLE"
L18_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L17_1.m_CharStrID = L18_1
L18_1 = "L"
L17_1.m_Pos = L18_1
L18_1 = "뭘 이 정도를 가지고. 나도 자네들 활약은 잘 지켜 봤지. 아주 인상적이었어."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "お安い御用だ。私も君たちの活躍には注視していたが、大変印象深かったぞ。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Ah, don't mention it. I've been watching you operate down there, and it was most impressive."
L17_1.m_Talk_ENG = L18_1
L18_1 = "這種程度不算什麼。我也有看到你們的活躍表現，非常令人印象深刻啊。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "อ๋อ ไม่เป็นไรหรอก ผมดูพวกคุณทำงานอยู่ข้างล่าง และมันน่าประทับใจสุดๆ"
L17_1.m_Talk_THA = L18_1
L18_1 = "À, đừng nhắc đến việc đó. Tôi đã xem bạn hoạt động dưới đó, và đó là điều ấn tượng nhất."
L17_1.m_Talk_VTN = L18_1
L18_1 = "这种程度不算什么。我也有好好关注你们的活跃表现。真的令人印象深刻。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Nicht der Rede wert. Ich habe Sie im Einsatz gesehen und war sehr beeindruckt."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Oh, je vous en prie. Je vous ai regardé travailler là-bas, et c'était très impressionnant."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "EP5_ACT5_STAGE6_END@218#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 218
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 215
L18_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L18_1.m_CharStrID = L19_1
L19_1 = "L"
L18_1.m_Pos = L19_1
L19_1 = "앞으로도 일이 있을 때 종종 부르도록 하겠네."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "今後も頼みたいことがあったら、時々呼ぶことにしよう。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "I think I'll be asking you for help every once in a while."
L18_1.m_Talk_ENG = L19_1
L19_1 = "如果以後有什麼事，我們也會經常叫你們的。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ผมว่าผมคงต้องขอให้พวกคุณช่วยเป็นครั้งคราวนะ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Tôi nghĩ thỉnh thoảng tôi sẽ nhờ bạn giúp đỡ."
L18_1.m_Talk_VTN = L19_1
L19_1 = "如果以后有什么事，我们也会经常叫你们的。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Wahrscheinlich werde ich Sie noch das eine oder andere Mal um Hilfe bitten."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Je pense que je solliciterai votre aide de temps à autre à l'avenir."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "EP5_ACT5_STAGE6_END@219#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 219
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 215
L19_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_SERIOUS"
L20_1 = "YUMI_POLICE_NULL_NULL"
L19_1.m_CharStrID = L20_1
L20_1 = "R"
L19_1.m_Pos = L20_1
L20_1 = "저희는 공무원입니다. 기업의 이윤을 위해 싸우지는 않습니다만......"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "私たちは公務員です。企業の利益のために戦ったりはしないのですが……"
L19_1.m_Talk_JPN = L20_1
L20_1 = "We're civil servants. I'm afraid we don't fight for the benefit of a private company..."
L19_1.m_Talk_ENG = L20_1
L20_1 = "我們是公務員，不能為了企業的利益戰鬥……"
L19_1.m_Talk_TWN = L20_1
L20_1 = "เราเป็นข้าราชการ เกรงว่าเราจะสู้เพื่อผลประโยชน์ของบริษัทเอกชนไม่ได้นะคะ..."
L19_1.m_Talk_THA = L20_1
L20_1 = "Chúng tôi là công chức. Tôi e rằng chúng tôi không đấu tranh vì lợi ích của một công ty tư nhân..."
L19_1.m_Talk_VTN = L20_1
L20_1 = "我们是公务员。虽然我们不会为了公司的利润而战斗……"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Wir sind Beamte. Als solche arbeiten wir leider nicht für gewinnorientierte Privatunternehmen."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Nous sommes des fonctionnaires. Nous ne nous engageons hélas pas pour le bénéfice d'entreprises privées..."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
