L22_1 = "EP5_ACT5_STAGE6_END@221#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 221
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 215
L21_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "SOYEONG_POLICE_NULL_NULL"
L21_1.m_CharStrID = L22_1
L22_1 = "R_M_I"
L21_1.m_Pos = L22_1
L22_1 = "네, 다음에도 잘 부탁 드릴게요~"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "はい、次回もよろしくお願いします～。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "We also look forward to working with you again."
L21_1.m_Talk_ENG = L22_1
L22_1 = "好的，那下次也請多指教了～"
L21_1.m_Talk_TWN = L22_1
L22_1 = "เราก็หวังว่าจะได้ร่วมงานกับคุณอีกเหมือนกัน"
L21_1.m_Talk_THA = L22_1
L22_1 = "Chúng tôi cũng mong muốn được làm việc với bạn một lần nữa."
L21_1.m_Talk_VTN = L22_1
L22_1 = "嗯，下次也拜托你们了~"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Auch wir freuen uns darauf, wieder mit Ihnen zu arbeiten."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Nous avons également hâte de travailler à nouveau avec vous."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "EP5_ACT5_STAGE6_END@222#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 222
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 215
L22_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "UNIT_PRIDE"
L22_1.m_Face = L23_1
L23_1 = "SOYEONG_POLICE_NULL_NULL"
L22_1.m_CharStrID = L23_1
L23_1 = "R"
L22_1.m_Pos = L23_1
L23_1 = "대신 기브 앤 테이크 아시죠? 저희 쪽에서 지원이 필요할 때도 좀 도와주시면 좋겠네요."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "でも、その代わり、ギブアンドテイクってわかりますよね？\n我々に支援が必要な時にも助けていただけると。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "And I believe you're sensible enough to return a favor. I'd appreciate it if you could provide assistance when need be."
L22_1.m_Talk_ENG = L23_1
L23_1 = "不過你知道什麼叫有往有來嗎？我們這邊需要支援的時候，希望你們也能來幫忙。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "และฉันเชื่อว่าคุณมีสติมากพอที่จะตอบแทนเรา ฉันจะขอบคุณมากถ้าคุณจะให้ความช่วยเหลือเวลาที่เราต้องการ"
L22_1.m_Talk_THA = L23_1
L23_1 = "Và tôi tin rằng bạn đủ nhạy bén để trả ơn. Tôi đánh giá cao nếu bạn có thể hỗ trợ khi cần thiết."
L22_1.m_Talk_VTN = L23_1
L23_1 = "不过你们知道什么叫有往有来吗？我方需要支援的时候，希望你们也能提供帮忙。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ich gehe davon aus, dass Sie so vernünftig sind, Gefälligkeiten zu erwidern, und uns unterstützen werden, wenn es nötig ist."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Et comme je sais que vous êtes quelqu'un de parole, je sais que je pourrai également compter sur vous lorsque j'aurai besoin de votre assistance."
L22_1.m_Talk_FRA = L23_1
