L26_1 = "EP5_ACT5_STAGE6_END@225#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 225
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 215
L25_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "JOHN_MASON_NULL_NULL"
L25_1.m_CharStrID = L26_1
L25_1.m_Pos = "C"
L26_1 = "그래도 간만에 만나보는 건설적인 동업자였어."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "まあ、久々に出会った頼れる同業者だったよ。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Well, you've been a very pleasant company during this operation."
L25_1.m_Talk_ENG = L26_1
L26_1 = "不過我好久沒有遇到這麼有建設性的合作夥伴了。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "พวกคุณเป็นพรรคพวกที่ดีมากในปฏิบัติการครั้งนี้"
L25_1.m_Talk_THA = L26_1
L26_1 = "Chà, bạn luôn là một công ty rất dễ chịu trong quá trình hoạt động này."
L25_1.m_Talk_VTN = L26_1
L26_1 = "好歹是久违的建设性合作伙伴啊。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Nun, du warst während dieser Operation eine angenehme Gesellschaft."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Eh bien, ce fut un plaisir de travailler en votre compagnie pendant cette opération."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP5_ACT5_STAGE6_END@226#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 226
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 215
L26_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "UNIT_LAUGH"
L26_1.m_Face = L27_1
L27_1 = "JOHN_MASON_NULL_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "C"
L27_1 = "앞으로도 잘해 보자고, 파트너."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "今後ともよろしくな、パートナー。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "I look forward to continuing working with you, Partner."
L26_1.m_Talk_ENG = L27_1
L27_1 = "以後也一起好好幹吧，合夥人。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "หวังว่าจะได้ทำงานด้วยกันต่อไปนะ พาร์ทเนอร์"
L26_1.m_Talk_THA = L27_1
L27_1 = "Tôi mong được tiếp tục làm việc với bạn, Đối Tác."
L26_1.m_Talk_VTN = L27_1
L27_1 = "以后也一起好好干吧，合伙人。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Ich freue mich darauf, wieder mit dir zu arbeiten, Partner."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Je me réjouis de continuer à travailler avec vous, partenaire."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP5_ACT5_STAGE6_END@227#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 227
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 215
L27_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L28_1 = "TOMY_MASON_NULL_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "C"
L28_1 = "파트너라고 하기엔 회사 크기가 너무 다른데, 그냥 빌붙는 거 아냐?"
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "パートナーにしては会社の規模が違いすぎるし、ただの寄生じゃないか？"
L27_1.m_Talk_JPN = L28_1
L28_1 = "The size difference between the two companies is too great to consider them partners. Aren't you just trying to mooch?"
L27_1.m_Talk_ENG = L28_1
L28_1 = "要說合夥人，公司的規模未免也相差太大了，你這是在自抬身價吧？"
L27_1.m_Talk_TWN = L28_1
L28_1 = "ขนาดของสองบริษัทแตกต่างกันเกินกว่าจะจัดว่าพวกเขาเป็นพาร์ทเนอร์กันนะ นี่คุณแค่พยายามยอเหรอ?"
L27_1.m_Talk_THA = L28_1
L28_1 = "Sự khác biệt về quy mô giữa hai công ty là quá lớn để có thể coi họ là đối tác. Bạn chỉ đang cố gắng để lợi dụng thôi phải không?"
L27_1.m_Talk_VTN = L28_1
L28_1 = "要说合伙人，双方公司规模是不是相差太大了，你这只是在拍马屁而已吧？"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Der Größenunterschied zwischen unseren Unternehmen ist zu groß, als dass sie Partner sein könnten. Willst du hier nicht vielmehr einfach nur rumlungern?"
L27_1.m_Talk_DEU = L28_1
L28_1 = "La différence de taille entre les deux entreprises est trop grande pour vous considérer comme des partenaires. Ou alors t'essaies de quémander un peu ?"
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
