L28_1.m_Face = "UNIT_HATE"
L29_1 = "JOHN_MASON_NULL_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L28_1.m_Crash = 15
L29_1 = "......파트너라고! 파트너!"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "……パートナーだよ！　パートナー！"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Shut up! We're partners!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "……就是合夥人啦！合夥人！"
L28_1.m_Talk_TWN = L29_1
L29_1 = "หุบปากน่า! เราเป็นพาร์ทเนอร์กัน!"
L28_1.m_Talk_THA = L29_1
L29_1 = "Im đi! Chúng tôi là đối tác của nhau!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "……我说了是合伙人啊！合伙人！"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Halt die Klappe! Wir sind Partner!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Ferme-la ! On est des partenaires !"
L28_1.m_Talk_FRA = L29_1
