L30_1 = "EP5_ACT5_STAGE6_END@229#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 229
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 215
L29_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L30_1 = "서윤 양, 자네도 고생 많았네. 어려운 결정이었는데 마지막까지 잘해 줬어."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "シズカ君、君もご苦労だった。難しい決定だったのに、最後までよくやってくれた。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "You did great, Seo Yoon. You've done well despite all the complicated circumstances."
L29_1.m_Talk_ENG = L30_1
L30_1 = "徐芸小姐，妳也辛苦啦。儘管是個艱難的決定，但直到最後妳都做得很好。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ทำได้ดีมากนะ ซอ ยุน คุณทำได้ดีทั้งที่ต้องเผชิญสถานการณ์ซับซ้อนมากมาย"
L29_1.m_Talk_THA = L30_1
L30_1 = "Bạn đã làm rất tốt, Seo Yoon. Bạn đã làm tốt dù gặp phải những tình huống phức tạp."
L29_1.m_Talk_VTN = L30_1
L30_1 = "徐芸小姐，你也辛苦啦。尽管是艰难的决定，但直到最后你都做得很好。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Sie haben sich in Anbetracht der schwierigen Umstände gut geschlagen, Seo Yoon."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Vous vous en êtes bien sortie, Seo Yoon. Vous avez bien fait, et ceci malgré les circonstances compliquées."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "EP5_ACT5_STAGE6_END@230#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 230
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 215
L30_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "UNIT_PRIDE"
L30_1.m_Face = L31_1
L31_1 = "SEOYOON_REPLACER_NULL_LANCE"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "C"
L31_1 = "별 말씀을요. 보상만 확실하다면 앞으로도 만족하실 만한 서비스를 제공해드리겠습니다."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "とんでもありません。報酬さえ弾むなら、これからもご満足頂けるサービスを提供いたしましょう。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Thank you. I'll gladly be at your service, as long as the pay is right."
L30_1.m_Talk_ENG = L31_1
L31_1 = "哪裡哪裡。只要確實收到了報酬，今後我也會向您提供令人滿意的服務。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ขอบคุณค่ะ ฉันยินดีรับใช้ ตราบใดที่คุณจ่ายเงินครบ"
L30_1.m_Talk_THA = L31_1
L31_1 = "Cảm ơn bạn. Tôi sẵn lòng phục vụ bạn, miễn là với mức lương phù hợp."
L30_1.m_Talk_VTN = L31_1
L31_1 = "哪里哪里。只要切实收到了报酬，今后我也会向您提供令人满意的服务。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Danke. Ich stehe Ihnen mit Freuden zu Diensten, solange die Bezahlung stimmt."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Je vous remercie. Tant que la solde sera correcte, je resterai volontiers à votre service."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP5_ACT5_STAGE6_END@231#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 231
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 215
L31_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "UNIT_LAUGH"
L31_1.m_Face = L32_1
L32_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "하하, 자넨 확실히 테러리스트 보다 용병이 잘 어울리는 것 같아."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "ハハ、やっぱり君は、テロリストより傭兵のほうが天職だな。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Hah hah, you're definitely a better fit for a mercenary than a terrorist."
L31_1.m_Talk_ENG = L32_1
L32_1 = "哈哈，比起恐怖分子，妳果然更適合當傭兵呢。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ฮ่าๆ คุณนี่เหมาะกับการเป็นทหารรับจ้างมากกว่าเป็นผู้ก่อการร้ายจริงๆ"
L31_1.m_Talk_THA = L32_1
L32_1 = "Ha ha, bạn chắc chắn phù hợp với công việc lính đánh thuê hơn là khủng bố."
L31_1.m_Talk_VTN = L32_1
L32_1 = "哈哈，果然比起破坏分子，还是佣兵的身份更适合你。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ha, ha, Sie machen sich als Söldner definitiv besser denn als Terrorist."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Ha ha, vous êtes définitivement mieux adaptée au métier de mercenaire qu'à celui de terroriste."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
