L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 233
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 215
L33_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_IDLE"
L34_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "실비아 양도 이번 일에 대한 감사 표시로 펜릴 소대를 훈장 수여 대상으로 추천하겠다더군요."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "シルビアさんも今回の件のお礼として、フェンリル小隊を勲章授与対象に推薦してくれるそうです。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Sylvia said that she was going to put the Fenrir squad members up as medal candidates."
L33_1.m_Talk_ENG = L34_1
L34_1 = "希爾維亞小姐為了對這次事件表達感謝，會推薦芬里爾小隊作為授勳對象。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "ซิลเวียบอกว่าเธอจะเสนอให้สมาชิกหน่วยเฟนเรียร์ได้รับเหรียญ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Sylvia nói rằng cô ấy sẽ đề xuất các thành viên của Tiểu Đội Fenrir làm ứng cử viên nhận huy chương."
L33_1.m_Talk_VTN = L34_1
L34_1 = "听说希尔薇娅小姐为了表达对这次事件的感激，会推荐芬里尔小队作为勋章授予对象哦。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Sylvia hat gesagt, sie schlägt die Mitglieder des Fenrir-Trupps für eine Auszeichnung vor."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Sylvia a dit qu'elle allait recommander les membres de l'escouade Fenrir au tableau des médailles."
L33_1.m_Talk_FRA = L34_1
