L37_1 = "UNIT_LAUGH"
L36_1.m_Face = L37_1
L37_1 = "JOOSHIYOON_FENRIR_NULL_NULL"
L36_1.m_CharStrID = L37_1
L37_1 = "R"
L36_1.m_Pos = L37_1
L37_1 = "하하, 훈장이라니 쑥스럽네요."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "ハハ、勲章だなんて、照れるなぁ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Hah hah, that's too kind."
L36_1.m_Talk_ENG = L37_1
L37_1 = "哈哈，竟然要給我們勳章，好害羞唷。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ฮ่าฮ่า ใจดีจริงๆ"
L36_1.m_Talk_THA = L37_1
L37_1 = "Ha ha, cô ấy thật là tốt bụng."
L36_1.m_Talk_VTN = L37_1
L37_1 = "哈哈，竟然要给我们授予勋章，真是不好意思啊。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Ha, ha. Das ist zu freundlich."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Ha ha, c'est très gentil."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP5_ACT5_STAGE6_END@237#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 237
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 215
L37_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L38_1 = "L"
L37_1.m_Pos = L38_1
L37_1.m_Crash = 20
L38_1 = "뭐, 뭘 그렇게나...... 그 정도까진 필요 없는데......"
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "な、何をそんなに……そこまでは必要ないのに……"
L37_1.m_Talk_JPN = L38_1
L38_1 = "That's unexpected. Really, that doesn't sound necessary at all."
L37_1.m_Talk_ENG = L38_1
L38_1 = "這、這麼……明明不用做到這種地步……"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ไม่น่าเชื่อลเยนะ แต่ฟังดูไม่จำเป็นเลย"
L37_1.m_Talk_THA = L38_1
L38_1 = "Thật là bất ngờ. Thực sự, điều đó nghe không cần thiết chút nào."
L37_1.m_Talk_VTN = L38_1
L38_1 = "怎、怎么还……明明没必要为我们做到这种地步……"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Das kommt unerwartet. Und ist auch unnötig."
L37_1.m_Talk_DEU = L38_1
L38_1 = "C'est plutôt inattendu. Mais ça n'est vraiment pas nécessaire."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
