L40_1 = "EP5_ACT5_STAGE6_END@239#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 239
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 215
L39_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "UNIT_PRIDE"
L39_1.m_Face = L40_1
L40_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "C"
L40_1 = "동감입니다. 팔아먹지도 못하는 훈장 따위 딱히 쓸모도 없는데 말입니다."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "同感です。売り飛ばすこともできない勲章なんて、大して使い道もないのに。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "I couldn't agree more. What good does a medal do for anyone anyway?"
L39_1.m_Talk_ENG = L40_1
L40_1 = "就是啊。不能變賣的勳章一點用都沒有。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เห็นด้วย เหรียญพวกนั้นจะมีประโยชน์อะไร?"
L39_1.m_Talk_THA = L40_1
L40_1 = "Tôi cũng nghĩ vậy. Huy chương có ích gì cơ chứ?"
L39_1.m_Talk_VTN = L40_1
L40_1 = "我也这么觉得。勋章这种东西又不能卖了换钱，一点儿用都没有。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Finde ich auch. Wozu ist eine Auszeichnung schon gut?"
L39_1.m_Talk_DEU = L40_1
L40_1 = "À qui le dis-tu. À quoi ça sert une médaille de toute façon ?"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "EP5_ACT5_STAGE6_END@240#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 240
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 215
L40_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "C"
L41_1 = "계약금이나 올려줄 것이지......"
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "契約金でも上げてくれればいいのに……"
L40_1.m_Talk_JPN = L41_1
L41_1 = "A single pay raise would be worth a hundred times more than a medal."
L40_1.m_Talk_ENG = L41_1
L41_1 = "應該給我們漲一點契約金啊……"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ขึ้นเงินเดือนสักนิดยังมีค่ามากกว่าเหรียญนั่นร้อยเท่า"
L40_1.m_Talk_THA = L41_1
L41_1 = "Tăng lương sẽ có giá trị gấp trăm lần so với một chiếc huy chương."
L40_1.m_Talk_VTN = L41_1
L41_1 = "应该给我们涨一点儿佣金啊……"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Da ist mir eine schnöde Gehaltserhöhung hundertmal lieber."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Cent médailles ne valent pas une bonne vieille augmentation de salaire !"
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
