L47_1 = "UNIT_LAUGH"
L46_1.m_Face = L47_1
L47_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "C"
L47_1 = "어쨌든 길었던 이번 사건도 잘 마무리가 되었군요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "とにかく、長引いた今回の事件も無事に収束しましたね。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Anyway, this long journey has finally ended."
L46_1.m_Talk_ENG = L47_1
L47_1 = "總之，這次漫長的事件也終於迎來了圓滿的結局。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "เอาละ ในที่สุดการเดินทางเอายาวนานก็จบลงแล้ว"
L46_1.m_Talk_THA = L47_1
L47_1 = "Dù sao thì cuộc hành trình dài dằng dặc này cuối cùng cũng đã kết thúc."
L46_1.m_Talk_VTN = L47_1
L47_1 = "总之，这次漫长的事件也终于迎来了圆满的结局。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Eine lange Reise neigt sich ihrem Ende zu."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Enfin bref, ce long périple touche à sa fin."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "EP5_ACT5_STAGE6_END@247#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 247
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 215
L47_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "C"
L48_1 = "부사장의 입에 발린 격려야 아무래도 상관없겠지만, 다들 수고 많았습니다."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "副社長のお決まりの激励なんてどうでもいいでしょうけど、皆さん、ご苦労さまでした。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "I know it's lame, but I'd like to tell you as the vice president. Good work, everyone."
L47_1.m_Talk_ENG = L48_1
L48_1 = "雖然這種慰勞的話出自我這副總的口中沒什麼大不了的，但大家都辛苦了。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ฉันรู้ว่ามันน้ำเน่านะ แต่ในฐานะรองประธาน ฉันก็อยากบอกทุกคนว่าเก่งมาก"
L47_1.m_Talk_THA = L48_1
L48_1 = "Tôi biết là chưa thỏa đáng, nhưng tôi muốn nói với bạn với tư cách là phó chủ tịch. Tốt lắm mọi người."
L47_1.m_Talk_VTN = L48_1
L48_1 = "虽然大家应该也不是很想听我这个二把手的鼓励，不过我还是说一句，各位辛苦了。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Ich weiß, es klingt abgedroschen, aber als Vizevorsitzende möchte ich euch sagen: Gute Arbeit!"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Je sais que ça sonne creux mais, en tant que vice-présidente, j'aimerais vous féliciter. Beau travail, tout le monde."
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
L49_1 = "EP5_ACT5_STAGE6_END@248#Talk"
L48_1.m_CutScenKey_Talk = L49_1
L49_1 = 248
L48_1.m_CutScenProcessKey = L49_1
L48_1.m_CutScenID = 215
L48_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L48_1.m_bWaitClick = true
L48_1.m_fWaitTime = 0
L48_1.m_Face = "UNIT_IDLE"
L49_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "C"
L49_1 = "사장님께서도 결과에 흡족해 하시는 것 같으니 무단이탈에 대한 징계는 시말서 정도로만 끝내도록 하겠습니다."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "社長も結果に満足しているようですから、\n無断離脱に対する懲戒は、始末書程度にしておきましょう。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Since our CEO seems to be satisfied with the result, there will be no punishment for going AWOL as long as you submit a letter of apology."
L48_1.m_Talk_ENG = L49_1
L49_1 = "老闆也對這次的結果非常滿意，所以關於這次擅離職守的懲罰，你們只要寫個悔過書就可以了。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ในเมื่อ CEO ของเราดูจะพอใจกับผลลัพธ์ เราจะไม่มีการลงโทษคนที่ลางานโดยไม่แจ้ง ตราบใดที่พวกคุณส่งจดหมายขอโทษ"
L48_1.m_Talk_THA = L49_1
L49_1 = "Vì CEO của chúng tôa dường như hài lòng với kết quả, nên sẽ không có hình phạt nào nếu bạn tham gia AWOL miễn là bạn gửi thư xin lỗi."
L48_1.m_Talk_VTN = L49_1
L49_1 = "似乎老板也对这次的结果很满意，所以关于这次擅离职守的惩罚，老板决定只要你们写悔过书就可以了。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Da unser Geschäftsführer mit dem Ergebnis zufrieden ist, gibt es keine Strafe für das unerlaubte Entfernen von der Truppe, sofern ihr ein Entschuldigungsschreiben verfasst."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Puisque notre président semble être satisfait du résultat, il n'y aura pas de punition pour les actes de désertion, du moment que vous rédigez une lettre d'excuses."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
L50_1 = "EP5_ACT5_STAGE6_END@249#Talk"
L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 249
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 215
L49_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L49_1.m_bWaitClick = true
L49_1.m_fWaitTime = 0
L50_1 = "UNIT_LAUGH"
L49_1.m_Face = L50_1
L50_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L49_1.m_CharStrID = L50_1
L49_1.m_Pos = "C"
L50_1 = "그리고 이제부터 화끈한 뒤풀이 회식을 예약해 놓았네!"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "それから、この後は豪華な打ち上げパーティーを予約しておいたのだ！"
L49_1.m_Talk_JPN = L50_1
L50_1 = "And I'd like everyone to know that I've reserved a place to celebrate the successful end of this mission."
L49_1.m_Talk_ENG = L50_1
L50_1 = "另外，我已經預約好了激動人心的聚餐啦！"
L49_1.m_Talk_TWN = L50_1
L50_1 = "และฉันก็อยากให้ทุกคนรู้ว่า ฉันจองที่สำหรับการฉลองความสำเร็จของภารกิจนี้ไว้แล้ว"
L49_1.m_Talk_THA = L50_1
L50_1 = "Và tôi muốn mọi người biết rằng tôi đã đặt một chỗ để kỷ niệm sự kết thúc thành công của nhiệm vụ này."
L49_1.m_Talk_VTN = L50_1
L50_1 = "另外，已经预约好激动人心的聚餐啦！"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Und Sie sollen wissen, dass ich eine Location angemietet habe, um unseren Erfolg zu feiern."
L49_1.m_Talk_DEU = L50_1
L50_1 = "Et j'aimerais que tout le monde sache que j'ai réservé un endroit pour fêter la réussite de notre mission."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
