L3_1 = "EP5_ACT5_STAGE6_END@252#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 252
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 215
L2_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Face = "UNIT_SURPRISE"
L3_1 = "LENA_COFFIN_NULL_NULL"
L2_1.m_CharStrID = L3_1
L3_1 = "L"
L2_1.m_Pos = L3_1
L3_1 = "저, 정말인가요? 지난 번처럼 구내식당에서 하는 건 아니겠죠?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "ほ、本当ですか？　前回同様、社員食堂でするんじゃないですよね？"
L2_1.m_Talk_JPN = L3_1
L3_1 = "R-really? It's not the in-house cafeteria like last time, is it?"
L2_1.m_Talk_ENG = L3_1
L3_1 = "真、真的嗎？不會又像上次那樣，在公司內部的食堂聚餐吧？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "จะ-จริงเหรอ? ไม่ใช่ที่โรงอาหารในบริษัทแบบคราวก่อนใช่ไหม?"
L2_1.m_Talk_THA = L3_1
L3_1 = "T-thật không? Không phải là quán ăn như lần trước chứ, phải không?"
L2_1.m_Talk_VTN = L3_1
L3_1 = "真，真的吗？不会又像上次那样在公司内部食堂聚餐吧？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Echt? Aber nicht wieder in der Kantine, wie letztes Mal?"
L2_1.m_Talk_DEU = L3_1
L3_1 = "V-Vraiment ? C'est pas la cafétéria comme la dernière fois, hein ?"
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "EP5_ACT5_STAGE6_END@253#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 253
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 215
L3_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_SERIOUS"
L4_1 = "CHLOE_COFFIN_NULL_NULL"
L3_1.m_CharStrID = L4_1
L4_1 = "R"
L3_1.m_Pos = L4_1
L4_1 = "정령님께서 소고기가 아니면 흉액을 내리겠다고 속삭이고 계십니다."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "精霊様が牛肉じゃなければ、災いを与えるとささやいておられます。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "The Great Spirit is whispering to me that there's going to be a disaster if it's not a steak."
L3_1.m_Talk_ENG = L4_1
L4_1 = "精靈大人悄悄地告訴我，如果沒有牛排的話，它就要降下災禍了。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "วิญญาณที่ยิ่งใหญ่กำลังกระซิบกับฉันว่าหายนะจะบังเกิดถ้าไม่ใช่ร้านสเต็ก"
L3_1.m_Talk_THA = L4_1
L4_1 = "Linh Hồn Vĩ Đại đại đang thì thầm với tôi rằng sẽ có một thảm họa nếu không có bít tết."
L3_1.m_Talk_VTN = L4_1
L4_1 = "精灵大人悄悄告诉我，如果没有牛肉的话它就要降下灾祸了。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Der Große Geist flüstert mir zu, dass es eine Katastrophe gibt, wenn er kein Steak bekommt."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Le Grand esprit me murmure qu'une catastrophe aura lieu si ce n'est pas un grill."
L3_1.m_Talk_FRA = L4_1
