L7_1 = "EP5_ACT5_STAGE6_END@256#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 256
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 215
L6_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "UNIT_PRIDE"
L6_1.m_Face = L7_1
L7_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L6_1.m_CharStrID = L7_1
L7_1 = "L"
L6_1.m_Pos = L7_1
L7_1 = "걱정 말게 아주 화끈한 곳으로 잡아두라고 했으니까. 그렇지 않나, 관리부장?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "心配無用だ。大変豪華な場所を用意するように伝えたからな、そうだろ、管理部長？"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Rest assured. It's going to be hell of a party. Isn’t that right, Manager Kim?"
L6_1.m_Talk_ENG = L7_1
L7_1 = "不用擔心，畢竟我已經說了要找個激動人心的地方聚餐了。對吧，管理部長？"
L6_1.m_Talk_TWN = L7_1
L7_1 = "วางใจเถอะ มันจะเป็นปาร์ตี้ที่สุดเหวี่ยงเลยละ ถูกไหม ผู้จัดการคิม?"
L6_1.m_Talk_THA = L7_1
L7_1 = "Hãy yên tâm. Sẽ là một buổi tiệc hoành tráng. Có phải vậy không, Quản Lý Kim?"
L6_1.m_Talk_VTN = L7_1
L7_1 = "不用担心，毕竟我已经说了要找个激动人心的地方聚餐了。对吧，管理部长？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Seien Sie versichert, es wird eine Mordsparty werden! Ist doch so, Manager Kim, oder?"
L6_1.m_Talk_DEU = L7_1
L7_1 = "Rassurez-vous. Ça va être une fête d'enfer. N'est-ce pas, directrice Kim ?"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "EP5_ACT5_STAGE6_END@257#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 257
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 215
L7_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "KIMHANA_COFFIN_NULL_NULL"
L7_1.m_CharStrID = L8_1
L8_1 = "R"
L7_1.m_Pos = L8_1
L8_1 = "네! 멋진 장소를 물색해 두겠습니다. 관리부의 능력을 믿어 주세요!"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "はい！　ステキな場所を用意しています。管理部の力を信じてください！"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Of course! I'll make sure it's at the perfect place. You can count on the Managerial Department!"
L7_1.m_Talk_ENG = L8_1
L8_1 = "是的！我會找個好地方的。請相信管理部的能力吧！"
L7_1.m_Talk_TWN = L8_1
L8_1 = "แน่นอน! ฉันจะจัดงานในที่ที่ดีที่สุด เชื่อใจแผนกบริหารได้เลยค่ะ!"
L7_1.m_Talk_THA = L8_1
L8_1 = "Tất nhiên! Tôi sẽ đảm bảo tổ chức ở một nơi hoàn hảo. Bạn có thể tin tưởng vào Bộ Phận Quản Lý!"
L7_1.m_Talk_VTN = L8_1
L8_1 = "是的！我会找个好地方的。请相信管理部的能力吧！"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Aber sicher! Ich sorge für die perfekte Location. Verlassen Sie sich auf die Führungsabteilung!"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Bien sûr ! Je vais m'assurer que l'endroit soit idéal. Vous pouvez compter sur la Direction !"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "EP5_ACT5_STAGE6_END@258#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 258
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 215
L8_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Face = "UNIT_SERIOUS"
L9_1 = "MACHINEGAP_COFFIN_NULL_NULL"
L8_1.m_CharStrID = L9_1
L9_1 = "L"
L8_1.m_Pos = L9_1
L9_1 = "아, 그리고 난 좀 늦게 도착할 예정이니 다들 먼저 가 있게."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "あ、それから、私は少し到着が遅れる予定だから、みんな先に行くと良い。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Oh, and don't wait for me. I'll be a little late."
L8_1.m_Talk_ENG = L9_1
L9_1 = "啊對了，我會晚點到，所以大家就先去吧。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "อ๋อ แล้วก็ไม่ต้องรอผมนะ ผมอาจไปสายนิดหน่อย"
L8_1.m_Talk_THA = L9_1
L9_1 = "Ồ, và đừng đợi tôi. Tôi sẽ đến muộn một chút."
L8_1.m_Talk_VTN = L9_1
L9_1 = "啊还有，我会晚点到，各位先去吧。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Ach, und warten Sie nicht auf mich. Ich komme etwas später."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Oh, et ne m'attendez pas. Je serai un peu en retard."
L8_1.m_Talk_FRA = L9_1
