L12_1 = "EP5_ACT5_STAGE6_END@261#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 261
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 215
L11_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L11_1.m_bWaitClick = true
