L11_1.m_Face = "UNIT_SURPRISE"
L11_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L12_1 = "L"
L11_1.m_Pos = L12_1
L12_1 = "어? 아직 남은 일이라도 있어?"
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "え？　まだ残ってる仕事があるの？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Huh? Do you still have work left to do?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "嗯？你還有什麼事沒做好嗎？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "เอ๊ะ? ยังมีงานต้องทำอีกเหรอคะ?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Hử? Bạn vẫn còn phải làm việc ư?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "嗯？还有什么事没做好吗？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Was? Haben Sie noch zu tun?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Ah ? Vous avez encore du travail ?"
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
L13_1 = "EP5_ACT5_STAGE6_END@262#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 262
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 215
L12_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L13_1 = "L"
L12_1.m_Pos = L13_1
L13_1 = "서윤 일도 그렇고, 물어볼 게 많았는데......"
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "シズカのこともそうだし、聞きたいことがたくさんあるのに……"
L12_1.m_Talk_JPN = L13_1
L13_1 = "I wanted to ask you about what happened with Seo Yoon and many other things..."
L12_1.m_Talk_ENG = L13_1
L13_1 = "徐芸的事也是，明明我還有好多想問你的……"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ฉันอยากถามคุณเรื่องสิ่งที่เกิดขึ้นกับซอ ยุนและอะไรอีกหลายอย่าง..."
L12_1.m_Talk_THA = L13_1
L13_1 = "Tôi muốn hỏi bạn về những điều đã xảy ra với Seo Yoon và nhiều thứ khác..."
L12_1.m_Talk_VTN = L13_1
L13_1 = "徐芸的事也是，明明我还有好多想问你的……"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Ich wollte Sie fragen, was mit Seo Yoon passiert ist, und vieles andere …"
L12_1.m_Talk_DEU = L13_1
L13_1 = "Je voulais vous demander ce qui s'est passé avec Seo Yoon, et plein d'autres choses..."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "EP5_ACT5_STAGE6_END@263#Talk"
L13_1.m_CutScenKey_Talk = L14_1
L14_1 = 263
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 215
L13_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L13_1.m_CharStrID = L14_1
L14_1 = "R"
L13_1.m_Pos = L14_1
L14_1 = "사장님께서는 새로운 직원의 채용을 위해 잠시 다녀오실 곳이 있습니다."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "社長は新しい社員の採用のために、ちょっと寄り道されるんです。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Boss has to interview a new employee of the company."
L13_1.m_Talk_ENG = L14_1
L14_1 = "老闆為了錄用新員工的事情，暫時得先離開。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "บอสมีสัมภาษณ์พนักงานใหม่ของบริษัทน่ะ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Ông Chủ phải phỏng vấn một nhân viên mới của công ty."
L13_1.m_Talk_VTN = L14_1
L14_1 = "有一些关于录用新员工的事，需要老板去一下。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Der Boss muss ein Vorstellungsgespräch führen."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Le patron doit faire passer un entretien à une nouvelle employée de l'entreprise."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "EP5_ACT5_STAGE6_END@264#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 264
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 215
L14_1.m_CutScenStrID = "EP5_ACT5_STAGE6_END"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Face = "UNIT_IDLE"
L15_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L14_1.m_CharStrID = L15_1
L15_1 = "R"
L14_1.m_Pos = L15_1
L15_1 = "면접을 마치는 대로 돌아오실 테니 걱정 마세요."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "面接が終わり次第参加しますから、心配なさらず。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "It won't take long, so don't worry."
L14_1.m_Talk_ENG = L15_1
L15_1 = "面試結束就會回來了，不用擔心。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ไม่นานหรอก ไม่ต้องห่วง"
L14_1.m_Talk_THA = L15_1
L15_1 = "Sẽ không mất nhiều thời gian đâu, vì vậy đừng lo lắng."
