L15_1.m_fTalkTime = 0.03
L16_1 = "面接？　まさかうちの会社に新人が入るの？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "An interview? There's going to be a rookie in the company?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "面試？我們公司該不會要有新員工了吧？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "สัมภาษณ์เหรอ? จะมีเด็กใหม่มาเข้าบริษัทเหรอ?"
L15_1.m_Talk_THA = L16_1
L16_1 = "Một cuộc phỏng vấn? Sắp có tân binh trong công ty?"
L15_1.m_Talk_VTN = L16_1
L16_1 = "面试？难道我们公司有新员工吗？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Ein Vorstellungsgespräch? Es kommt ein Frischling ins Unternehmen?"
