L19_1 = "어쩌면 미나 양에게도 새로운 후배가 생길 수도 있겠군."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "ひょっとすると、ミナ君にも新しい後輩ができるかもしれないな。"
