L19_1 = "說不定米娜小姐也會有新的後輩呢。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ถึงตอนนั้นคุณอาจจะต้องสอนเยอะหน่อยนะ มีนา"
L18_1.m_Talk_THA = L19_1
L19_1 = "Bạn có thể phải tốn thời gian dạy dỗ rất nhiều nếu việc tuyển dụng diễn ra thành công, Mina."
L18_1.m_Talk_VTN = L19_1
L19_1 = "说不定米娜小姐也会有新的后辈呢。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Und falls es klappt, müssen Sie ihm viel beibringen, Mina."
L18_1.m_Talk_DEU = L19_1
