L27_1 = "왜, 왜 그렇게 바라보는 거야?"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "ど、どうしてそんな風に見つめるの？"
L26_1.m_Talk_JPN = L27_1
L27_1 = "W-why are you looking at me like that?"
L26_1.m_Talk_ENG = L27_1
L27_1 = "幹、幹嘛這樣盯著我？"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ทะ-ทำไมมองฉันอย่างนั้นล่ะ?"
L26_1.m_Talk_THA = L27_1
L27_1 = "T-tại sao bạn lại nhìn tôi như vậy?"
L26_1.m_Talk_VTN = L27_1
L27_1 = "为、为什么这么看着我？"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Warum siehst du mich so an?"
L26_1.m_Talk_DEU = L27_1
L27_1 = "P-Pourquoi tu me regardes comme ça ?"
L26_1.m_Talk_FRA = L27_1
