L28_1 = "何でもありません。ただ、ちょっと性格が変わったかなと思って。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "It's nothing. I just had a feeling that you've changed a little."
L27_1.m_Talk_ENG = L28_1
L28_1 = "沒什麼。只是覺得米娜小姐的性格好像有點變了。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "เปล่า ก็แค่รู้สึกว่าเธอเปลี่ยนไปนิดหน่อย"
L27_1.m_Talk_THA = L28_1
L28_1 = "Không có gì. Tôi chỉ có cảm giác rằng bạn đã thay đổi một chút."
L27_1.m_Talk_VTN = L28_1
L28_1 = "也不是什么大事。只是觉得米娜小姐的性格好像有点变了。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Ach, nichts. Ich hatte bloß den Eindruck, du hast dich irgendwie verändert."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Pour rien. J'ai juste l'impression que tu as un peu changé."
L27_1.m_Talk_FRA = L28_1
